function readJson(key, fallback) {
  try {
    return JSON.parse(localStorage.getItem(key)) || fallback;
  } catch {
    return fallback;
  }
}

function writeJson(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}

function normalizeActiveSpace(value) {
  return value === "products" ? "products" : "learning";
}

function activeNavigationRoute() {
  if (activeSpace === "learning") {
    return route === "progress" ? "progress" : "home";
  }

  if (route === "law" || route === "glossary" || route === "contract-review") {
    return route;
  }

  return "home";
}

function renderSpaceShell() {
  const definition = spaceDefinitions[activeSpace];
  const currentNavRoute = activeNavigationRoute();
  const brandButton = document.querySelector("[data-brand-menu]");
  const currentSpaceLabel = document.querySelector("[data-current-space-label]");
  const nav = document.querySelector(".bottom-nav");

  body.dataset.space = activeSpace;

  if (brandButton) {
    brandButton.setAttribute("aria-label", `Поточний простір: ${definition.label}. Обрати інший простір Anodos`);
  }
  if (currentSpaceLabel) {
    currentSpaceLabel.textContent = definition.label;
  }

  document.querySelectorAll("[data-brand-menu-space]").forEach((button) => {
    const isActive = button.dataset.brandMenuSpace === activeSpace;
    button.setAttribute("aria-checked", String(isActive));
    button.classList.toggle("brand-menu-option-active", isActive);
  });

  if (nav) {
    nav.setAttribute("aria-label", `Навігація простору «${definition.label}»`);
    nav.innerHTML = definition.navigation.map((item) => `
      <button
        type="button"
        data-route="${escapeHtml(item.route)}"
        class="${item.route === currentNavRoute ? "nav-item nav-item-active" : "nav-item"}"
      >${escapeHtml(item.label)}</button>
    `).join("");
  }
}

function setBrandMenu(open) {
  brandMenuOpen = Boolean(open);
  const button = document.querySelector("[data-brand-menu]");
  const panel = document.querySelector("[data-brand-menu-panel]");
  if (button) {
    button.setAttribute("aria-expanded", brandMenuOpen ? "true" : "false");
  }
  if (panel) {
    panel.hidden = !brandMenuOpen;
  }
  if (brandMenuOpen) {
    window.requestAnimationFrame(() => {
      document.querySelector("[data-brand-menu-space][aria-checked='true']")?.focus();
    });
  }
}

function setActiveSpace(nextSpace, nextRoute = "home") {
  activeSpace = normalizeActiveSpace(nextSpace);
  localStorage.setItem(activeSpaceKey, activeSpace);
  window.clearTimeout(routeTransitionTimer);
  window.clearTimeout(routeTransitionInTimer);
  activeModuleSectionId = "";
  activeStateCompensationView = "";
  contractAccessGranted = false;
  pendingContractTemplateId = "";
  contractPasswordError = "";
  pendingRoute = "";
  pendingLessonId = "";
  route = nextRoute;
  body.classList.remove("route-is-changing");
  screen.classList.remove("screen-transition-out", "screen-transition-in");
  setBrandMenu(false);
  setCompassOpen(false);
  render();
  window.scrollTo(0, 0);
}

function setCompassOpen(open, focusSearch = false) {
  compassOpen = Boolean(open);
  if (compassOpen && !compassSearchTerm && scenarioSearchTerm) {
    compassSearchTerm = scenarioSearchTerm;
  }
  renderCompass();
  if (compassOpen && focusSearch) {
    window.requestAnimationFrame(() => {
      const input = document.getElementById("compassSearch");
      input?.focus();
      input?.setSelectionRange(input.value.length, input.value.length);
    });
  }
}

function renderCompass() {
  const button = document.querySelector("[data-open-compass]");
  if (button) {
    button.setAttribute("aria-expanded", compassOpen ? "true" : "false");
  }
  body.classList.toggle("compass-open", compassOpen);
  if (!compassPanel) {
    return;
  }
  compassPanel.hidden = !compassOpen;
  if (!compassOpen) {
    compassPanel.innerHTML = "";
    return;
  }

  const hasQuery = compassSearchTerm.trim().length > 0;
  compassPanel.innerHTML = `
    <section class="compass-card" role="dialog" aria-modal="false" aria-labelledby="compassTitle">
      <header class="compass-head">
        <div>
          <p class="eyebrow">Компас Anodos</p>
          <h2 id="compassTitle">Де шукати відповідь?</h2>
        </div>
        <button class="compass-close" type="button" data-close-compass aria-label="Закрити компас">×</button>
      </header>
      <label class="compass-search-label" for="compassSearch">
        <span>Ситуація Клієнта</span>
        <input
          id="compassSearch"
          type="search"
          autocomplete="off"
          placeholder="Опишіть ситуацію Клієнта"
          value="${escapeHtml(compassSearchTerm)}"
        />
      </label>
      ${hasQuery ? "" : `<p class="compass-hint">Опишіть ситуацію простими словами, а Anodos підкаже, де шукати відповідь.</p>`}
      <div id="compassSearchResults" class="compass-results" aria-live="polite"></div>
    </section>
  `;
  renderCompassResults();
}

function renderCompassResults() {
  const node = document.getElementById("compassSearchResults");
  if (!node) {
    return;
  }

  const { profile, results } = scenarioSearchResults(compassSearchTerm);
  if (!profile.terms.length) {
    node.innerHTML = "";
    return;
  }

  if (!results.length) {
    node.innerHTML = `
      <div class="scenario-empty compass-empty">
        <p>Нічого точного не знайшов. Спробуйте коротше: франшиза, бізнес-центр, компенсація премії, Munich Re.</p>
      </div>
    `;
    return;
  }

  node.innerHTML = `
    <div class="scenario-result-meta">
      <span>${results.length} результатів</span>
      ${profile.labels.length ? `<small>${profile.labels.map(escapeHtml).join(" · ")}</small>` : ""}
    </div>
    <div class="scenario-result-list">
      ${results.map(renderScenarioResultCard).join("")}
    </div>
  `;
}

function normalizeEmail(value) {
  return String(value || "").trim().toLowerCase();
}

function isBritmarkEmail(value) {
  return /^[^\s@]+@britmark\.com$/i.test(String(value || "").trim());
}

function currentUser() {
  return registeredUsers.find((user) => user.id === currentUserId) || null;
}

function isAuthorizedUser(user) {
  return Boolean(user && isBritmarkEmail(user.email));
}

function authorizedUsers() {
  return registeredUsers.filter(isAuthorizedUser);
}

function saveRegisteredUsers() {
  writeJson(usersKey, registeredUsers);
}

function progressForCurrentUser() {
  if (!currentUserId) {
    return readJson(progressKey, {});
  }
  return progressByUser[currentUserId] || {};
}

function saveCurrentProgress() {
  if (!currentUserId) {
    writeJson(progressKey, progress);
    return;
  }
  progressByUser[currentUserId] = progress;
  writeJson(progressByUserKey, progressByUser);
  void syncCurrentParticipant("progress");
}

function clearCurrentUser() {
  currentUserId = "";
  localStorage.removeItem(currentUserKey);
  progress = {};
}

function setCurrentUser(userId) {
  const selectedUser = registeredUsers.find((user) => user.id === userId) || null;
  if (!isAuthorizedUser(selectedUser)) {
    clearCurrentUser();
    return false;
  }
  currentUserId = userId;
  localStorage.setItem(currentUserKey, userId);
  progress = progressForCurrentUser();
  selectedUser.email = normalizeEmail(selectedUser.email);
  selectedUser.lastSeenAt = new Date().toISOString();
  delete selectedUser.organization;
  delete selectedUser.role;
  saveRegisteredUsers();
  return true;
}

function createUserId() {
  return `user-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
}

function initialsFor(user) {
  const name = user?.fullName || user?.email || "Ά";
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) {
    return "Ά";
  }
  return parts.slice(0, 2).map((part) => part[0]).join("").toUpperCase();
}

function renderProfileAvatar(user, size = "compact") {
  const className = size === "large" ? "profile-avatar profile-avatar-large" : "profile-avatar";
  if (user?.photo) {
    return `<div class="${className}" data-profile-photo-preview><img src="${escapeHtml(user.photo)}" alt="" /></div>`;
  }
  return `<div class="${className}" data-profile-photo-preview><span>${escapeHtml(initialsFor(user))}</span></div>`;
}

function profilePhotoFromFile(file) {
  if (!file || !file.size || !file.type.startsWith("image/")) {
    return Promise.resolve("");
  }

  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = () => {
      const image = new Image();
      image.onload = () => {
        const maxSize = 420;
        const scale = Math.min(1, maxSize / Math.max(image.width, image.height));
        const width = Math.max(1, Math.round(image.width * scale));
        const height = Math.max(1, Math.round(image.height * scale));
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const context = canvas.getContext("2d");
        context.drawImage(image, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", 0.82));
      };
      image.onerror = () => resolve("");
      image.src = String(reader.result || "");
    };
    reader.onerror = () => resolve("");
    reader.readAsDataURL(file);
  });
}

function escapeCsv(value) {
  return `"${String(value ?? "").replaceAll('"', '""')}"`;
}

function downloadTextFile(filename, text, type) {
  const blob = new Blob([text], { type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function exportRegistrationData(format) {
  const exportedAt = new Date().toISOString();
  const exportableUsers = authorizedUsers();
  if (format === "json") {
    const payload = {
      product: "Anodos",
      exportedAt,
      users: exportableUsers.map((user) => ({
        id: user.id,
        fullName: user.fullName,
        email: user.email,
        photo: user.photo || "",
        registeredAt: user.registeredAt,
        lastSeenAt: user.lastSeenAt || "",
        progress: progressByUser[user.id] || {}
      }))
    };
    downloadTextFile(`anodos-users-${Date.now()}.json`, JSON.stringify(payload, null, 2), "application/json;charset=utf-8");
    return;
  }

  const rows = [[
    "ПІБ",
    "Email",
    "Дата реєстрації",
    "Останній вхід",
    "Модуль",
    "Прогрес",
    "Тест",
    "Пройдено",
    "Оновлено"
  ]];

  exportableUsers.forEach((user) => {
    const userProgress = progressByUser[user.id] || {};
    lessons.forEach((lesson) => {
      const itemProgress = userProgress[lesson.id] || {};
      rows.push([
        user.fullName,
        user.email,
        user.registeredAt,
        user.lastSeenAt || "",
        lesson.title,
        itemProgress.done ? "100" : itemProgress.score || "0",
        itemProgress.score || "",
        itemProgress.done ? "так" : "ні",
        itemProgress.updatedAt || ""
      ]);
    });
  });

  const csv = rows.map((row) => row.map(escapeCsv).join(",")).join("\n");
  downloadTextFile(`anodos-users-${Date.now()}.csv`, csv, "text/csv;charset=utf-8");
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function escapeTsv(value) {
  return String(value || "").replaceAll("\t", " ").replaceAll(/\s*\n+\s*/g, " ").trim();
}

function contractReviewFileId(file, index = 0) {
  return `${file.name}-${file.size}-${file.lastModified || index}`;
}

function contractReviewFileExtension(name) {
  const match = String(name || "").toLowerCase().match(/\.[a-z0-9]+$/);
  return match ? match[0] : "";
}

function isContractReviewFile(file) {
  return contractReviewSupportedExtensions.includes(contractReviewFileExtension(file.name));
}

function contractReviewCanAutoReadFile(fileRecord) {
  const extension = contractReviewFileExtension(fileRecord?.name);
  if (extension === ".doc" || extension === ".docx" || extension === ".txt") {
    return true;
  }
  if (extension === ".pdf") {
    return window.location.protocol !== "file:";
  }
  return false;
}

function contractReviewInitialStatus(fileRecord) {
  const extension = contractReviewFileExtension(fileRecord?.name);
  if (extension === ".docx") {
    return "готовий до аналізу";
  }
  if (extension === ".pdf") {
    return window.location.protocol === "file:"
      ? "PDF у локальному режимі не читається. Для аналізу збережи як DOC/DOCX або відкрий HTTPS-версію"
      : "готовий до аналізу, якщо PDF має текстовий шар";
  }
  if (extension === ".doc") {
    return "готовий до аналізу як старий Word DOC";
  }
  if (extension === ".xls" || extension === ".xlsx") {
    return "Excel можна додати як супровідний файл, але договір треба завантажити у DOC або DOCX";
  }
  return "формат не читається автоматично";
}

function contractReviewFormatSize(bytes) {
  const size = Number(bytes || 0);
  if (size >= 1024 * 1024) {
    return `${Math.round((size / 1024 / 1024) * 10) / 10} MB`;
  }
  return `${Math.max(1, Math.round(size / 1024))} KB`;
}

function contractReviewYearFromName(name) {
  const years = String(name || "").match(/20\d{2}/g) || [];
  return years.length ? Number(years[years.length - 1]) : 0;
}

function contractReviewScore(file) {
  const year = contractReviewYearFromName(file.name);
  if (year) {
    return year * 10000000000000 + Number(file.lastModified || 0);
  }
  return Number(file.lastModified || 0);
}

function contractReviewDecodeEntities(value) {
  const textarea = document.createElement("textarea");
  textarea.innerHTML = String(value || "");
  return textarea.value;
}

function contractReviewXmlToText(xml) {
  return contractReviewDecodeEntities(String(xml || "")
    .replace(/<w:tab\/>/g, "\t")
    .replace(/<w:br\/>/g, "\n")
    .replace(/<\/w:tc>/g, " | ")
    .replace(/<\/w:tr>/g, "\n")
    .replace(/<\/w:p>/g, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/\u00a0/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim());
}

function contractReviewNormalizeText(text) {
  return String(text || "")
    .replace(/\u00a0/g, " ")
    .replace(/\u0007/g, "\n")
    .replace(/[\u000b\u000c]/g, "\n")
    .replace(/[\u0000-\u0006\u0008\u000e-\u001f]/g, "")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function contractReviewAssetUrl(path) {
  return new URL(path, window.location.href).href;
}

async function contractReviewReadDocx(fileRecord) {
  if (!window.JSZip) {
    throw new Error("JSZip не завантажився.");
  }

  const zip = await window.JSZip.loadAsync(fileRecord.file);
  const xmlNames = Object.keys(zip.files).filter((name) =>
    /^word\/(document|header\d+|footer\d+|footnotes|endnotes|comments)\.xml$/i.test(name)
  );
  const xmlParts = await Promise.all(xmlNames.map((name) => zip.files[name].async("string")));
  return contractReviewNormalizeText(xmlParts.map(contractReviewXmlToText).filter(Boolean).join("\n\n"));
}

async function contractReviewPdfModule() {
  if (!contractReviewPdfModulePromise) {
    contractReviewPdfModulePromise = import(contractReviewAssetUrl("./assets/vendor/pdf.min.mjs")).then((module) => {
      module.GlobalWorkerOptions.workerSrc = contractReviewAssetUrl("./assets/vendor/pdf.worker.min.mjs");
      return module;
    });
  }
  return contractReviewPdfModulePromise;
}

async function contractReviewReadPdf(fileRecord) {
  if (window.location.protocol === "file:") {
    return "";
  }

  const pdfjs = await contractReviewPdfModule();
  const data = new Uint8Array(await fileRecord.file.arrayBuffer());
  const pdf = await pdfjs.getDocument({ data, disableWorker: true }).promise;
  const pageTexts = [];
  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const content = await page.getTextContent();
    const text = content.items.map((item) => item.str || "").join(" ");
    if (text.trim()) {
      pageTexts.push(text.trim());
    }
  }
  return contractReviewNormalizeText(pageTexts.join("\n\n"));
}

function contractReviewReadUInt16LE(bytes, offset) {
  return bytes[offset] | (bytes[offset + 1] << 8);
}

function contractReviewReadInt32LE(bytes, offset) {
  return (bytes[offset] | (bytes[offset + 1] << 8) | (bytes[offset + 2] << 16) | (bytes[offset + 3] << 24)) | 0;
}

function contractReviewReadUInt32LE(bytes, offset) {
  return contractReviewReadInt32LE(bytes, offset) >>> 0;
}

function contractReviewOleSectorOffset(sectorId, sectorSize) {
  return 512 + sectorId * sectorSize;
}

function contractReviewReadOleSectorChain(bytes, fat, startSector, sectorSize, sizeLimit = Infinity) {
  const sectors = [];
  const seen = new Set();
  let sectorId = startSector;
  let total = 0;

  while (sectorId >= 0 && sectorId !== -2 && !seen.has(sectorId) && total < sizeLimit) {
    seen.add(sectorId);
    const offset = contractReviewOleSectorOffset(sectorId, sectorSize);
    if (offset < 0 || offset >= bytes.length) {
      break;
    }
    const take = Math.min(sectorSize, sizeLimit - total, bytes.length - offset);
    sectors.push(bytes.slice(offset, offset + take));
    total += take;
    sectorId = fat[sectorId];
  }

  const result = new Uint8Array(sectors.reduce((sum, sector) => sum + sector.length, 0));
  let position = 0;
  sectors.forEach((sector) => {
    result.set(sector, position);
    position += sector.length;
  });
  return result;
}

function contractReviewReadOleStream(bytes, streamName) {
  const signature = [0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1];
  if (!signature.every((value, index) => bytes[index] === value)) {
    return null;
  }

  const sectorSize = 1 << contractReviewReadUInt16LE(bytes, 30);
  const fatSectorCount = contractReviewReadUInt32LE(bytes, 44);
  const directoryStart = contractReviewReadInt32LE(bytes, 48);
  const difatStart = contractReviewReadInt32LE(bytes, 68);
  const difatSectorCount = contractReviewReadUInt32LE(bytes, 72);
  const fatSectorIds = [];

  for (let offset = 76; offset < 512; offset += 4) {
    const sectorId = contractReviewReadInt32LE(bytes, offset);
    if (sectorId >= 0) {
      fatSectorIds.push(sectorId);
    }
  }

  let difatSector = difatStart;
  for (let difatIndex = 0; difatIndex < difatSectorCount && difatSector >= 0; difatIndex += 1) {
    const offset = contractReviewOleSectorOffset(difatSector, sectorSize);
    const sectorIdsPerDifat = sectorSize / 4 - 1;
    for (let index = 0; index < sectorIdsPerDifat; index += 1) {
      const sectorId = contractReviewReadInt32LE(bytes, offset + index * 4);
      if (sectorId >= 0) {
        fatSectorIds.push(sectorId);
      }
    }
    difatSector = contractReviewReadInt32LE(bytes, offset + sectorIdsPerDifat * 4);
  }

  const fat = [];
  fatSectorIds.slice(0, fatSectorCount).forEach((sectorId) => {
    const offset = contractReviewOleSectorOffset(sectorId, sectorSize);
    for (let position = 0; position < sectorSize; position += 4) {
      fat.push(contractReviewReadInt32LE(bytes, offset + position));
    }
  });

  const directoryBytes = contractReviewReadOleSectorChain(bytes, fat, directoryStart, sectorSize);
  for (let offset = 0; offset + 128 <= directoryBytes.length; offset += 128) {
    const nameLength = contractReviewReadUInt16LE(directoryBytes, offset + 64);
    if (nameLength < 2) {
      continue;
    }

    let name = "";
    for (let position = 0; position < nameLength - 2; position += 2) {
      const charCode = contractReviewReadUInt16LE(directoryBytes, offset + position);
      if (charCode) {
        name += String.fromCharCode(charCode);
      }
    }

    if (name !== streamName) {
      continue;
    }

    const startSector = contractReviewReadInt32LE(directoryBytes, offset + 116);
    const size = contractReviewReadUInt32LE(directoryBytes, offset + 120);
    return contractReviewReadOleSectorChain(bytes, fat, startSector, sectorSize, size);
  }

  return null;
}

function contractReviewUtf16Score(text) {
  const cyrillicMatches = text.match(/[А-Яа-яІіЇїЄєҐґ]/g) || [];
  return cyrillicMatches.length * 3 + text.length;
}

function contractReviewExtractUtf16Text(bytes, startOffset = 0) {
  const chunks = [];
  let chunk = "";

  for (let index = startOffset; index + 1 < bytes.length; index += 2) {
    const charCode = contractReviewReadUInt16LE(bytes, index);
    const isReadable =
      charCode === 9 ||
      charCode === 10 ||
      charCode === 13 ||
      charCode === 32 ||
      charCode === 0x00a0 ||
      (charCode >= 0x0021 && charCode <= 0x007e) ||
      (charCode >= 0x0400 && charCode <= 0x052f) ||
      (charCode >= 0x2010 && charCode <= 0x203a) ||
      charCode === 0x2116;

    if (isReadable && charCode !== 0) {
      chunk += String.fromCharCode(charCode);
      continue;
    }

    if (chunk.length >= 5) {
      chunks.push(chunk);
    }
    chunk = "";
  }

  if (chunk.length >= 5) {
    chunks.push(chunk);
  }

  return chunks.join("\n");
}

function contractReviewDocFindPieceTable(tableStream, offset, length) {
  if (!tableStream || offset < 0 || length < 5 || offset + length > tableStream.length) {
    return null;
  }

  let position = offset;
  const end = offset + length;
  while (position < end && tableStream[position] === 0x01) {
    if (position + 3 > end) {
      return null;
    }
    const propertyLength = contractReviewReadUInt16LE(tableStream, position + 1);
    position += 3 + propertyLength;
  }

  if (position + 5 > end || tableStream[position] !== 0x02) {
    return null;
  }

  const pieceTableLength = contractReviewReadUInt32LE(tableStream, position + 1);
  const pieceTableStart = position + 5;
  if (pieceTableLength < 4 || pieceTableStart + pieceTableLength > tableStream.length) {
    return null;
  }

  const pieceCount = (pieceTableLength - 4) / 12;
  if (!Number.isInteger(pieceCount) || pieceCount < 1) {
    return null;
  }

  const characterPositions = [];
  for (let index = 0; index <= pieceCount; index += 1) {
    characterPositions.push(contractReviewReadUInt32LE(tableStream, pieceTableStart + index * 4));
  }

  const pieces = [];
  const pieceDescriptorsStart = pieceTableStart + (pieceCount + 1) * 4;
  for (let index = 0; index < pieceCount; index += 1) {
    const descriptorOffset = pieceDescriptorsStart + index * 8;
    const compressedOffset = contractReviewReadUInt32LE(tableStream, descriptorOffset + 2);
    const compressed = Boolean(compressedOffset & 0x40000000);
    const storedOffset = compressedOffset & 0x3fffffff;
    pieces.push({
      cpStart: characterPositions[index],
      cpEnd: characterPositions[index + 1],
      fileOffset: compressed ? storedOffset >>> 1 : storedOffset,
      compressed
    });
  }

  return pieces;
}

function contractReviewDocPropertyEnabled(propertyBytes, sprmLowByte, sprmHighByte) {
  for (let index = 0; index + 2 < propertyBytes.length; index += 1) {
    if (
      propertyBytes[index] === sprmLowByte
      && propertyBytes[index + 1] === sprmHighByte
      && propertyBytes[index + 2] !== 0
    ) {
      return true;
    }
  }
  return false;
}

function contractReviewDocExcludedRanges(wordDocument, tableStream) {
  const tableOffset = contractReviewReadUInt32LE(wordDocument, 250);
  const tableLength = contractReviewReadUInt32LE(wordDocument, 254);
  if (!tableStream || tableLength < 12 || tableOffset + tableLength > tableStream.length) {
    return [];
  }

  const pageCount = (tableLength - 4) / 8;
  if (!Number.isInteger(pageCount) || pageCount < 1) {
    return [];
  }

  const pageNumbersOffset = tableOffset + (pageCount + 1) * 4;
  const ranges = [];
  for (let pageIndex = 0; pageIndex < pageCount; pageIndex += 1) {
    const pageNumber = contractReviewReadUInt32LE(tableStream, pageNumbersOffset + pageIndex * 4) & 0x003fffff;
    const pageOffset = pageNumber * 512;
    if (pageOffset < 0 || pageOffset + 512 > wordDocument.length) {
      continue;
    }

    const runCount = wordDocument[pageOffset + 511];
    const runOffsetsStart = pageOffset;
    const propertyPointersStart = pageOffset + (runCount + 1) * 4;
    for (let runIndex = 0; runIndex < runCount; runIndex += 1) {
      const runStart = contractReviewReadUInt32LE(wordDocument, runOffsetsStart + runIndex * 4);
      const runEnd = contractReviewReadUInt32LE(wordDocument, runOffsetsStart + (runIndex + 1) * 4);
      const propertyPointer = wordDocument[propertyPointersStart + runIndex] * 2;
      if (!propertyPointer || propertyPointer >= 511 || runEnd <= runStart) {
        continue;
      }

      const propertyLength = wordDocument[pageOffset + propertyPointer];
      const propertyStart = pageOffset + propertyPointer + 1;
      const propertyEnd = Math.min(propertyStart + propertyLength, pageOffset + 511);
      const propertyBytes = wordDocument.slice(propertyStart, propertyEnd);
      const deletedByRevision = contractReviewDocPropertyEnabled(propertyBytes, 0x00, 0x08);
      const hiddenField = contractReviewDocPropertyEnabled(propertyBytes, 0x02, 0x08);
      const hiddenText = contractReviewDocPropertyEnabled(propertyBytes, 0x3c, 0x08);
      if (deletedByRevision || hiddenField || hiddenText) {
        ranges.push({ start: runStart, end: runEnd });
      }
    }
  }

  return ranges
    .sort((left, right) => left.start - right.start || left.end - right.end)
    .reduce((merged, current) => {
      const previous = merged[merged.length - 1];
      if (previous && current.start <= previous.end) {
        previous.end = Math.max(previous.end, current.end);
      } else {
        merged.push({ ...current });
      }
      return merged;
    }, []);
}

function contractReviewDocOffsetIsExcluded(offset, excludedRanges) {
  let low = 0;
  let high = excludedRanges.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    const range = excludedRanges[middle];
    if (offset < range.start) {
      high = middle - 1;
    } else if (offset >= range.end) {
      low = middle + 1;
    } else {
      return true;
    }
  }
  return false;
}

function contractReviewDocDecodePieces(wordDocument, pieces, excludedRanges, characterLimit) {
  const windowsDecoder = new TextDecoder("windows-1251");
  const unicodeDecoder = new TextDecoder("utf-16le");
  const fragments = [];

  for (const piece of pieces) {
    const cpStart = Math.max(0, piece.cpStart);
    const cpEnd = Math.min(piece.cpEnd, characterLimit);
    const characterCount = cpEnd - cpStart;
    if (characterCount <= 0) {
      continue;
    }

    const bytesPerCharacter = piece.compressed ? 1 : 2;
    const byteLength = characterCount * bytesPerCharacter;
    if (piece.fileOffset < 0 || piece.fileOffset + byteLength > wordDocument.length) {
      continue;
    }

    const pieceBytes = wordDocument.slice(piece.fileOffset, piece.fileOffset + byteLength);
    const decoded = piece.compressed ? windowsDecoder.decode(pieceBytes) : unicodeDecoder.decode(pieceBytes);
    let visible = "";
    for (let index = 0; index < decoded.length; index += 1) {
      const fileOffset = piece.fileOffset + index * bytesPerCharacter;
      if (!contractReviewDocOffsetIsExcluded(fileOffset, excludedRanges)) {
        visible += decoded[index];
      }
    }
    fragments.push(visible);
  }

  return fragments.join("");
}

async function contractReviewReadDoc(fileRecord) {
  const bytes = new Uint8Array(await fileRecord.file.arrayBuffer());
  const wordDocument = contractReviewReadOleStream(bytes, "WordDocument");
  if (!wordDocument || wordDocument.length < 426) {
    return "";
  }

  const tableStreamName = contractReviewReadUInt16LE(wordDocument, 10) & 0x0200 ? "1Table" : "0Table";
  const tableStream = contractReviewReadOleStream(bytes, tableStreamName);
  const pieceTableOffset = contractReviewReadUInt32LE(wordDocument, 418);
  const pieceTableLength = contractReviewReadUInt32LE(wordDocument, 422);
  const characterLimit = contractReviewReadUInt32LE(wordDocument, 76);
  const pieces = contractReviewDocFindPieceTable(tableStream, pieceTableOffset, pieceTableLength);
  if (!tableStream || !pieces || !characterLimit) {
    return "";
  }

  const excludedRanges = contractReviewDocExcludedRanges(wordDocument, tableStream);
  const text = contractReviewNormalizeText(
    contractReviewDocDecodePieces(wordDocument, pieces, excludedRanges, characterLimit)
  );
  return contractReviewUtf16Score(text) >= 120 ? text : "";
}

async function contractReviewReadText(fileRecord) {
  const extension = contractReviewFileExtension(fileRecord.name);
  if (extension === ".docx") {
    return {
      text: await contractReviewReadDocx(fileRecord),
      status: "DOCX прочитано"
    };
  }

  if (extension === ".pdf") {
    const text = await contractReviewReadPdf(fileRecord);
    return {
      text,
      status: text
        ? "PDF прочитано"
        : window.location.protocol === "file:"
          ? "PDF у локальному file-режимі не читається. Для аналізу збережи як DOC/DOCX або відкрий HTTPS-версію"
          : "PDF не містить текстового шару"
    };
  }

  if (extension === ".doc") {
    const text = await contractReviewReadDoc(fileRecord);
    return {
      text,
      status: text ? "DOC прочитано" : "DOC не вдалося прочитати. Збережи файл у Word як DOCX"
    };
  }

  if (extension === ".txt") {
    return {
      text: contractReviewNormalizeText(await fileRecord.file.text()),
      status: "TXT прочитано"
    };
  }

  return {
    text: "",
    status: `${extension.toUpperCase().replace(".", "") || "Файл"} додано, але автозчитування зараз працює для DOC, DOCX і текстових PDF`
  };
}

function contractReviewCleanValue(value, maxLength = 220) {
  const cleaned = String(value || "")
    .replace(/\u00a0/g, " ")
    .replace(/\r/g, "\n")
    .replace(/\bFORMTEXT\b/gi, " ")
    .replace(/\s+/g, " ")
    .replace(/^[\s:;,\-–—|]+/, "")
    .replace(/[\s;,\-–—|]+$/, "")
    .trim();
  if (cleaned.length <= maxLength) {
    return cleaned;
  }
  return `${cleaned.slice(0, maxLength).replace(/\s+\S*$/, "")}...`;
}

function contractReviewIsPlaceholderValue(value) {
  const normalized = contractReviewNormalizeComparable(value)
    .replace(/[«»"']/g, "")
    .replace(/^\/+|\/+$/g, "")
    .trim();
  return !normalized
    || /formtext|mergeformat|п\.?і\.?б\.?\s*\/\s*(назва|найменування)|найменування:|номер$|адреса$|підрозділу$|місцезнаходження$|від імені якого діє$/.test(normalized)
    || /^(insurer|insured|beneficiary|company name|full name(?:\s*\/\s*company name)?|territory of insurance|insurance territory|legal address|address|sum insured|deductible|insurance rate|insurance premium)$/.test(normalized)
    || /^(страховик|страхувальник|вигодонабувач|назва|повна назва|територія страхування|страхова сума|франшиза|страховий тариф|страховий платіж)$/.test(normalized);
}

function contractReviewTextLines(text) {
  return String(text || "")
    .split(/[\r\n]+/)
    .map((line) => contractReviewCleanValue(line, 400))
    .filter(Boolean);
}

function contractReviewFindLineValue(lines, labels, options = {}) {
  const minLength = options.minLength || 2;
  const maxLength = options.maxLength || 220;
  const skipValue = /^(так|ні|наявний|відсутній|пункт|розділ)$/i;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const lowerLine = line.toLowerCase();
    const matchedLabel = labels.find((label) => lowerLine.includes(label.toLowerCase()));
    if (!matchedLabel) {
      continue;
    }

    const labelIndex = lowerLine.indexOf(matchedLabel.toLowerCase());
    const tail = contractReviewCleanValue(line.slice(labelIndex + matchedLabel.length), maxLength);
    if (
      tail.length >= minLength
      && !skipValue.test(tail)
      && !contractReviewIsPlaceholderValue(tail)
      && (!options.validate || options.validate(tail))
    ) {
      return tail;
    }

    for (let offset = 1; offset <= (options.lookahead || 5); offset += 1) {
      const nextLine = lines[index + offset] || "";
      if (!nextLine) {
        continue;
      }
      const nextLower = nextLine.toLowerCase();
      const looksLikeAnotherLabel = /^(?:страховик|страхувальник|вигодонабувач|франшиза|тариф|платіж|премія|адреса|договір|insurer|insured|beneficiary|deductible|insurance rate|insurance premium)(?:\s|[:/]|$)/.test(nextLower);
      if (
        !looksLikeAnotherLabel
        && nextLine.length >= minLength
        && !contractReviewIsPlaceholderValue(nextLine)
        && (!options.validate || options.validate(nextLine))
      ) {
        return contractReviewCleanValue(nextLine, maxLength);
      }
    }
  }

  return "";
}

function contractReviewFindContext(lines, patterns, maxLength = 260) {
  const patternList = patterns.map((pattern) => pattern instanceof RegExp ? pattern : new RegExp(pattern, "i"));
  const index = lines.findIndex((line) => patternList.some((pattern) => pattern.test(line)));
  if (index < 0) {
    return "";
  }
  return contractReviewCleanValue(lines.slice(index, index + 2).join(" "), maxLength);
}

function contractReviewFindLineIndex(lines, pattern, startIndex = 0) {
  const regex = pattern instanceof RegExp ? pattern : new RegExp(pattern, "i");
  return lines.findIndex((line, index) => index >= startIndex && regex.test(line));
}

function contractReviewNormalizePartyName(value) {
  const cleaned = contractReviewCleanValue(value, 260)
    .replace(/\s*\/\s*(?:LLC|JSC|PJSC|PrJSC|ARX Insurance|ARX IC)\b.*$/i, "")
    .replace(/\s*,?\s*(?:в особі|що надалі|надалі|іменован[а-яіїєґ]*|referred to as|represented by)(?:\s|$).*$/i, "")
    .replace(/\s*\((?:надалі|попередня назва|далі)(?:\s|$).*$/i, "")
    .replace(/^товариство з обмеженою відповідальністю(?=\s|[«"]|$)/i, "ТОВ")
    .replace(/^товариство з додатковою відповідальністю(?=\s|[«"]|$)/i, "ТДВ")
    .replace(/^приватне акціонерне товариство(?=\s|[«"]|$)/i, "ПрАТ")
    .replace(/^публічне акціонерне товариство(?=\s|[«"]|$)/i, "ПАТ")
    .replace(/^акціонерне товариство(?=\s|[«"]|$)/i, "АТ")
    .replace(/\s*\*\s*$/, "")
    .replace(/\s+"/g, " «")
    .replace(/"\s*/g, "» ")
    .replace(/[“]([^”]{1,160})[”]/g, "«$1»")
    .replace(/«\s+/g, "«")
    .replace(/\s+»/g, "»")
    .replace(/\s+/g, " ")
    .replace(/[\s,;:/]+$/, "")
    .trim();

  if (!cleaned) {
    return "";
  }
  return cleaned;
}

function contractReviewLineLooksLikePartyValue(line) {
  const normalized = contractReviewNormalizeComparable(line).replace(/[()]/g, "").trim();
  if (!normalized || contractReviewIsPlaceholderValue(line)) {
    return false;
  }
  if (/^\d[\d\s]*$/.test(normalized) || /^ua\d/i.test(normalized)) {
    return false;
  }
  if (/^(в особі|посада|п\.?і\.?б|діє|номер|дата|адреса|телефон|код єдрпоу|iban|р\/р|п\/р|рахунок|реквізити|bank details|резидент|ідентифікаційний|повна назва|найменування|full name|company name|legal address)/i.test(normalized)) {
    return false;
  }
  return /товариство|акціонерне|страхова компанія|банк|universalna|універсальна|магелан|бритмарк|приватне|(?:^|\s)(?:прат|тов|тдв|пат|ат|ск)(?:\s|[«"])|\bllc\b|\bjsc\b/i.test(line);
}

function contractReviewExtractParty(lines, headingPattern, options = {}) {
  const heading = headingPattern instanceof RegExp ? headingPattern : new RegExp(headingPattern, "i");
  let startIndexes = lines
    .map((line, index) => heading.test(line) ? index : -1)
    .filter((index) => index >= 0);
  if (options.firstHeadingOnly) {
    startIndexes = startIndexes.slice(0, 1);
  }
  const candidates = [];
  const maxLookahead = options.maxLookahead || 16;
  startIndexes.forEach((startIndex) => {
    const values = [];
    for (let index = startIndex + 1; index < Math.min(lines.length, startIndex + 1 + maxLookahead); index += 1) {
      const line = lines[index];
      if (/^(страховик|страхувальник|вигодонабувач|предмет договору|договір укладений|страхова сума|перелік страхових)/i.test(line)) {
        break;
      }
      if (!contractReviewLineLooksLikePartyValue(line)) {
        if (values.length) {
          break;
        }
        continue;
      }
      values.push(line);
      if (values.length >= (options.maxValueLines || 1)) {
        break;
      }
    }
    const normalized = contractReviewNormalizePartyName(values.join(" "));
    if (normalized) {
      candidates.push(normalized);
    }
  });

  return candidates
    .map((value) => ({
      value,
      score:
        (/[А-Яа-яІіЇїЄєҐґ]{3}/.test(value) ? 20 : 0)
        + (/^(?:ТОВ|ТДВ|АТ|ПрАТ|ПАТ|ДП|ПП|КП)(?:\s|[«"])/.test(value) ? 30 : 0)
        + (/(?:^|\s)(?:СК|страхова компанія)(?:\s|[«"])|«СК\s/i.test(value) ? 15 : 0)
        - (/\b(?:LLC|JSC|Insurance)\b/i.test(value) ? 20 : 0)
    }))
    .sort((left, right) => right.score - left.score || left.value.length - right.value.length)[0]?.value || "";
}

function contractReviewExtractInsurer(lines) {
  const legalCandidates = lines
    .filter((line) => /^(?:АТ|ПрАТ|ПАТ|ТДВ|акціонерне товариство|приватне акціонерне товариство|публічне акціонерне товариство|товариство з додатковою відповідальністю)(?:\s|[«"]).*(?:СК(?:\s|[«"])|«СК|страхова компанія)/i.test(line))
    .map(contractReviewNormalizePartyName)
    .filter(Boolean);
  return legalCandidates[0] || contractReviewExtractParty(lines, /^страховик\s*\/?\s*(?:insurer)?$/i);
}

function contractReviewExtractInsured(lines) {
  return contractReviewExtractParty(lines, /^страхувальник\s*\/?\s*(?:i?insured)?$/i, {
    maxLookahead: 18,
    firstHeadingOnly: true
  });
}

function contractReviewExtractBeneficiary(lines) {
  return contractReviewExtractParty(lines, /^вигодонабувач\s*\/?\s*(?:beneficiary)?$/i, {
    maxLookahead: 12,
    firstHeadingOnly: true
  });
}

function contractReviewExtractInsuredAddress(lines) {
  const withCadastralNumber = (address, addressIndex) => {
    let cadastralNumber = "";
    for (let offset = 0; offset <= 4; offset += 1) {
      const line = lines[addressIndex + offset] || "";
      const inline = line.match(/кадастровий номер\s*:?\s*([0-9]{8,}(?::[0-9]+)+)/i);
      if (inline) {
        cadastralNumber = inline[1];
        break;
      }
      if (/кадастровий номер/i.test(line)) {
        const nextLine = lines[addressIndex + offset + 1] || "";
        const nextMatch = nextLine.match(/^([0-9]{8,}(?::[0-9]+)+)$/);
        if (nextMatch) {
          cadastralNumber = nextMatch[1];
          break;
        }
      }
    }
    return cadastralNumber
      ? `${address}; кадастровий номер ${cadastralNumber}`
      : address;
  };

  const propertyIndex = contractReviewFindLineIndex(lines, /майно вважається застрахованим тільки за адресою/i);
  if (propertyIndex >= 0) {
    const tail = contractReviewCleanValue(lines[propertyIndex].replace(/^.*майно вважається застрахованим тільки за адресою(?:\s*\([^)]*\))?:?/i, ""), 260);
    if (tail && !contractReviewIsPlaceholderValue(tail)) {
      return withCadastralNumber(tail, propertyIndex);
    }
    for (let offset = 1; offset <= 4; offset += 1) {
      const line = lines[propertyIndex + offset] || "";
      if (/перелік страхових|страховим випадком|страхова сума/i.test(line)) {
        break;
      }
      if (/(м\.|місто|обл\.|область|вул\.|вулиц)/i.test(line)) {
        return withCadastralNumber(contractReviewCleanValue(line, 260), propertyIndex + offset);
      }
    }
  }

  const locationHeadingPatterns = [
    /^територія страхування$/i,
    /адреса місцезнаходження.*(?:застрахованого )?майна/i,
    /місцезнаходження.*(?:застрахованого )?майна/i
  ];
  const addressSignal = /(?:м\.|місто|смт|село|вул\.|вулиц|просп|пров\.|обл\.|область|р-н|район|с\/р|сільрад|комплекс будівель)/i;
  for (const headingPattern of locationHeadingPatterns) {
    const headingIndexes = lines
      .map((line, index) => headingPattern.test(line) ? index : -1)
      .filter((index) => index >= 0)
      .reverse();
    for (const headingIndex of headingIndexes) {
      const searchEnd = Math.min(lines.length, headingIndex + 55);
      for (let index = headingIndex + 1; index < searchEnd; index += 1) {
        const line = lines[index];
        if (/^(?:insurance territory|territory of insurance|адреса провадження|страхова сума|франшиза|страховий тариф)$/i.test(line)) {
          continue;
        }
        if (addressSignal.test(line) && !/юридична адреса|legal address/i.test(line)) {
          const address = contractReviewCleanValue(line.replace(/\s*\/\s*[A-Z].*$/, ""), 300);
          return withCadastralNumber(address, index);
        }
      }
    }
  }

  return "";
}

function contractReviewExtractProductName(lines) {
  const productIndex = contractReviewFindLineIndex(lines, /страхового продукту/i);
  if (productIndex >= 0) {
    const sameLine = contractReviewCleanValue(lines[productIndex].replace(/^.*страхового продукту/i, ""), 180);
    if (sameLine && !/договір|відповідно|зусп/i.test(sameLine)) {
      return contractReviewNormalizeProductText(sameLine);
    }
    const nextLine = lines[productIndex + 1] || "";
    if (nextLine && !/договір|відповідно|зусп/i.test(nextLine)) {
      return contractReviewNormalizeProductText(nextLine);
    }
  }

  const titleIndex = contractReviewFindLineIndex(lines, /добровільного страхування майна/i);
  if (titleIndex >= 0) {
    const fragment = lines.slice(titleIndex, titleIndex + 3).join(" ");
    if (/збитків від перерви у господарській діяльності/i.test(fragment)) {
      return "Добровільне страхування майна підприємств та збитків від перерви у господарській діяльності";
    }
    const parenthetical = fragment.match(/\((для[^)]+)\)/i);
    if (parenthetical) {
      return `Добровільне страхування майна (${contractReviewCleanValue(parenthetical[1], 160).replace(/АТ ОТП Банк/i, "АТ «ОТП Банк»")})`;
    }
    return "Добровільне страхування майна";
  }

  if (lines.some((line) => /страхування майна/i.test(line))) {
    return "Страхування майна";
  }
  return "";
}

function contractReviewNormalizeProductText(value) {
  const cleaned = contractReviewCleanValue(value, 180)
    .replace(/[«»"]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (/предмета іпотеки/i.test(cleaned)) {
    return "Страхування предмета іпотеки";
  }
  return cleaned;
}

function contractReviewExtractRiskSummary(lines) {
  return contractReviewClassifyRisks(lines.join("\n"));
}

function contractReviewRiskShortName(value) {
  const normalized = String(value || "").toLowerCase();
  if (/пожеж|вогонь|задим|вибух|блискав/.test(normalized)) {
    return "вогонь/вибух/блискавка";
  }
  if (/стих|природ|зсув|град|сніг|повін|сель|вітер/.test(normalized)) {
    return "стихійні/природні явища";
  }
  if (/осідан|просідан|провал|ґрунт/.test(normalized)) {
    return "осідання грунту";
  }
  if (/землетрус/.test(normalized)) {
    return "землетрус";
  }
  if (/^вплив вод/.test(normalized)) {
    return "вплив води";
  }
  if (/будівниц|реконструкц/.test(normalized)) {
    return "роботи поряд із застрахованим майном";
  }
  if (/аварії|тепло|газопостач|електричн|виробнич/.test(normalized)) {
    return "аварії інженерних мереж";
  }
  if (/вод|рідин|каналіза|опален|пожежогас/.test(normalized)) {
    return "вплив води";
  }
  if (/наїзд|зіткнен|транспорт/.test(normalized)) {
    return "наїзд/зіткнення ТЗ";
  }
  if (/літальн/.test(normalized)) {
    return "падіння літальних об'єктів";
  }
  if (/протиправ|крадіж|грабіж|розбій|хуліган|умисн/.test(normalized)) {
    return "протиправні дії третіх осіб";
  }
  if (/падіння дерев|падіння стовп|падіння.*конструкц/.test(normalized)) {
    return "падіння дерев/конструкцій";
  }
  return contractReviewCleanValue(value, 70).replace(/\s*\(.*/, "");
}

function contractReviewParseNumber(value) {
  const normalized = String(value || "")
    .replace(/\u00a0/g, " ")
    .replace(/\s/g, "")
    .replace(",", ".");
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : null;
}

function contractReviewFormatMoney(value) {
  if (!Number.isFinite(value)) {
    return "";
  }
  const formatted = value
    .toLocaleString("uk-UA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    .replace(/[\u00a0\u202f]/g, " ");
  return `${formatted} грн`;
}

function contractReviewFormatPercent(value) {
  if (!Number.isFinite(value)) {
    return "";
  }
  return `${value.toLocaleString("uk-UA", { minimumFractionDigits: 0, maximumFractionDigits: 4 })}%`;
}

function contractReviewStandaloneNumber(line) {
  const cleaned = String(line || "").replace(/\u00a0/g, " ").trim();
  if (/^\d{1,3}(?: \d{3})*(?:,\d{1,4})?$/.test(cleaned) || /^\d+,\d{1,4}$/.test(cleaned)) {
    return cleaned;
  }
  return "";
}

function contractReviewMoneyFromLine(line) {
  const cleaned = String(line || "").replace(/\u00a0/g, " ").trim();
  const match = cleaned.match(/^(\d{1,3}(?: \d{3})+(?:[,.]\d{1,2})?|\d{4,}(?:[,.]\d{1,2})?)\s*(?:грн\.?|uah)?(?:\s*\/.*)?$/i);
  return match ? contractReviewFormatMoney(contractReviewParseNumber(match[1])) : "";
}

function contractReviewPercentFromLine(line) {
  const cleaned = String(line || "").replace(/\u00a0/g, " ").trim();
  const match = cleaned.match(/^(\d{1,2}(?:[,.]\d{1,4})?)\s*%(?:\s*\/.*)?$/);
  return match ? contractReviewFormatPercent(contractReviewParseNumber(match[1])) : "";
}

function contractReviewRateFromTableLine(line) {
  const explicit = contractReviewPercentFromLine(line);
  if (explicit) {
    return explicit;
  }
  const standalone = String(line || "").replace(/\u00a0/g, " ").trim().match(/^(\d{1,2}[,.]\d{1,4})$/);
  const value = standalone ? contractReviewParseNumber(standalone[1]) : null;
  return Number.isFinite(value) && value > 0 && value < 10 ? contractReviewFormatPercent(value) : "";
}

function contractReviewDurationFromLine(line) {
  const cleaned = String(line || "").replace(/\u00a0/g, " ").trim();
  const match = cleaned.match(/^(\d{1,3})\s*(діб|дн(?:і|ів|я)|годин(?:и)?|місяц(?:ь|і|ів))(?:\s*\/.*)?$/i);
  return match ? `${match[1]} ${match[2].toLowerCase()}` : "";
}

function contractReviewFindNextParsedValue(lines, startIndex, parser, lookahead = 12) {
  if (startIndex < 0) {
    return "";
  }
  for (let index = startIndex; index <= Math.min(lines.length - 1, startIndex + lookahead); index += 1) {
    const value = parser(lines[index]);
    if (value) {
      return value;
    }
  }
  return "";
}

function contractReviewJoinCoverageValues(entries) {
  const found = entries.filter((entry) => entry.value);
  if (!found.length) {
    return "";
  }
  if (found.length === 1) {
    return found[0].value;
  }
  return found.map((entry) => `${entry.label}: ${entry.value}`).join("; ");
}

function contractReviewExtractFinancialValues(lines) {
  const sumLineIndex = contractReviewFindLineIndex(lines, /^загальна страхова сума(?:\s|$)/i);
  const premiumLineIndex = contractReviewFindLineIndex(lines, /^загальн(?:ий|а)\s+(?:страховий платіж|страхова премія)/i);
  const sumInsured = contractReviewExtractMoneyAfterLine(lines, sumLineIndex, 4);
  const premium = contractReviewExtractMoneyAfterLine(lines, premiumLineIndex, 4);

  const propertyTableStart = contractReviewFindLineIndex(lines, /перелік майна, що приймається на страхування/i);
  const propertyTableEnd = propertyTableStart >= 0
    ? contractReviewFindLineIndex(lines, /таблиця\s*2|дані щодо перерви у господарській діяльності/i, propertyTableStart + 1)
    : -1;
  let propertyRate = "";
  let propertyDeductible = "";
  let propertySumInsured = "";
  if (propertyTableStart >= 0) {
    const end = propertyTableEnd > propertyTableStart ? propertyTableEnd : Math.min(lines.length, propertyTableStart + 100);
    for (let index = propertyTableStart; index < end; index += 1) {
      const parsedRate = contractReviewRateFromTableLine(lines[index]);
      if (!parsedRate) {
        continue;
      }
      propertyRate = parsedRate;
      const moneyBeforeRate = [];
      for (let previous = index - 1; previous >= Math.max(propertyTableStart, index - 10); previous -= 1) {
        const parsedMoney = contractReviewMoneyFromLine(lines[previous]);
        if (parsedMoney) {
          moneyBeforeRate.push(parsedMoney);
          if (moneyBeforeRate.length >= 2) {
            break;
          }
        }
      }
      propertyDeductible = moneyBeforeRate[0] || "";
      propertySumInsured = moneyBeforeRate[1] || "";
      break;
    }
  }

  const businessInterruptionSection = contractReviewFindLineIndex(
    lines,
    /страхова сума.*франшиза.*страховий тариф.*перерви у господарській діяльності/i
  );
  const businessInterruptionRate = contractReviewFindNextParsedValue(
    lines,
    businessInterruptionSection,
    contractReviewPercentFromLine,
    18
  );
  const businessInterruptionDeductible = contractReviewFindNextParsedValue(
    lines,
    businessInterruptionSection,
    contractReviewDurationFromLine,
    18
  );
  const businessInterruptionTable = propertyTableEnd > propertyTableStart ? propertyTableEnd : -1;
  const businessInterruptionSumInsured = contractReviewFindNextParsedValue(
    lines,
    businessInterruptionTable,
    contractReviewMoneyFromLine,
    55
  );
  const maximumIndemnityIndex = contractReviewFindLineIndex(lines, /максимальний період відшкодування/i);
  let maximumIndemnityPeriod = "";
  if (maximumIndemnityIndex >= 0) {
    for (let index = maximumIndemnityIndex + 1; index <= Math.min(lines.length - 1, maximumIndemnityIndex + 10); index += 1) {
      const match = lines[index].match(/^(\d{1,3})(?:\s*місяц(?:ь|і|ів))?$/i);
      if (!match) {
        continue;
      }
      const months = Number(match[1]);
      const lastTwoDigits = months % 100;
      const lastDigit = months % 10;
      const monthLabel = lastTwoDigits >= 11 && lastTwoDigits <= 14
        ? "місяців"
        : lastDigit === 1
          ? "місяць"
          : lastDigit >= 2 && lastDigit <= 4
            ? "місяці"
            : "місяців";
      maximumIndemnityPeriod = `${months} ${monthLabel}`;
      break;
    }
  }

  const rate = contractReviewJoinCoverageValues([
    { label: "Майно", value: propertyRate },
    { label: "BI", value: businessInterruptionRate }
  ]);
  const deductible = contractReviewJoinCoverageValues([
    { label: "Майно", value: propertyDeductible },
    { label: "BI", value: businessInterruptionDeductible }
  ]);
  const coverageLimits = [
    propertySumInsured ? `Майно: ${propertySumInsured}` : "",
    businessInterruptionSumInsured ? `BI: ${businessInterruptionSumInsured}` : "",
    maximumIndemnityPeriod ? `максимальний період відшкодування: ${maximumIndemnityPeriod}` : ""
  ].filter(Boolean).join("; ");

  return { sumInsured, rate, premium, deductible, coverageLimits };
}

function contractReviewExtractLimits(lines) {
  const results = [];
  const explicitLimitPattern = /(?:субліміт|ліміт відповідальності|ліміт відшкодування|ліміт страхової виплати)/i;
  const inlineValuePattern = /(\d{1,3}(?:[ \u00a0]\d{3})+(?:[,.]\d{1,2})?\s*(?:грн\.?|uah|usd|eur)?|\d{1,2}(?:[,.]\d{1,4})?\s*%|\d{1,3}\s*(?:діб|дн(?:і|ів|я)|годин(?:и)?|місяц(?:ь|і|ів)))/i;

  lines.forEach((line, index) => {
    if (!explicitLimitPattern.test(line) || /визначення|означає|розуміється/i.test(line)) {
      return;
    }
    const inlineMatch = line.match(inlineValuePattern);
    if (inlineMatch) {
      results.push(contractReviewCleanValue(line, 240));
      return;
    }
    for (let offset = 1; offset <= 2; offset += 1) {
      const nextLine = lines[index + offset] || "";
      const parsedValue =
        contractReviewMoneyFromLine(nextLine)
        || contractReviewPercentFromLine(nextLine)
        || contractReviewDurationFromLine(nextLine);
      if (parsedValue) {
        results.push(`${contractReviewCleanValue(line, 180)}: ${parsedValue}`);
        break;
      }
    }
  });

  return [...new Set(results)].slice(0, 6).join("; ");
}

function contractReviewExtractMoneyAfterLine(lines, lineIndex, lookahead = 4) {
  if (lineIndex < 0) {
    return "";
  }
  for (let offset = 0; offset <= lookahead; offset += 1) {
    const line = lines[lineIndex + offset] || "";
    const direct = contractReviewMoneyFromLine(line);
    if (direct) {
      return direct;
    }
    const sameLineMatch = offset === 0
      ? line.match(/(?:становить|складає|дорівнює|:)\s*(\d{1,3}(?:[ \u00a0]\d{3})+(?:[,.]\d{1,2})?|\d{4,}(?:[,.]\d{1,2})?)\s*(?:грн\.?|uah)?/i)
      : null;
    if (sameLineMatch) {
      return contractReviewFormatMoney(contractReviewParseNumber(sameLineMatch[1]));
    }
  }
  return "";
}

function contractReviewExtractPremiumFromTable(moneyValues, hasExplicitRate) {
  const money = moneyValues.map((item) => item.value).filter((value) => value >= 1000);
  const premiumIndex = hasExplicitRate ? 2 : 2;
  return money[premiumIndex] ? contractReviewFormatMoney(money[premiumIndex]) : "";
}

function contractReviewExtractDeductibleFromTable(moneyValues, hasExplicitRate) {
  const money = moneyValues.map((item) => item.value).filter((value) => value >= 1000);
  const deductibleIndex = hasExplicitRate ? 3 : 3;
  return money[deductibleIndex] ? contractReviewFormatMoney(money[deductibleIndex]) : "";
}

function contractReviewDeriveRate(sumInsured, premium) {
  const sum = contractReviewParseNumber(String(sumInsured).replace(/[^\d,.\s]/g, ""));
  const premiumValue = contractReviewParseNumber(String(premium).replace(/[^\d,.\s]/g, ""));
  if (!sum || !premiumValue) {
    return "";
  }
  return contractReviewFormatPercent((premiumValue / sum) * 100);
}

function contractReviewExtractCoverageDatesFromLines(lines) {
  const candidatePatterns = [
    /№ періоду страхування|період \(рік\) страхування/i,
    /строк дії договору/i,
    /дата початку\s+дата закінчення|дата початку|початок$/i
  ];

  for (const pattern of candidatePatterns) {
    const scheduleIndex = contractReviewFindLineIndex(lines, pattern);
    if (scheduleIndex < 0) {
      continue;
    }
    const fragment = lines.slice(scheduleIndex, scheduleIndex + 18).join(" ");
    const dates = [...fragment.matchAll(/\d{1,2}[./]\d{1,2}[./]\d{2,4}/g)]
      .map((match) => contractReviewFormatDate(match[0]))
      .filter(Boolean);
    if (dates.length >= 2) {
      const distinctRange = dates.find((date, index) => index > 0 && date !== dates[0]);
      if (distinctRange) {
        return { startDate: dates[0], endDate: distinctRange };
      }
    }
  }
  return null;
}

function contractReviewExtractIntermediaryClause(lines) {
  const index = contractReviewFindLineIndex(lines, /договір укладений за посередництва|страхов(ий|ого) посередник|бритмарк|britmark/i);
  if (index < 0) {
    return "";
  }
  const collected = [];
  for (let offset = 0; offset <= 12; offset += 1) {
    const line = lines[index + offset] || "";
    if (offset > 0 && /^(зміна інформації|предмет договору|страхова сума|перелік страхових)/i.test(line)) {
      break;
    }
    collected.push(line);
  }
  const fragment = collected.join(" ");
  if (!/бритмарк|britmark|посередництва/i.test(fragment)) {
    return "";
  }
  return contractReviewCleanValue(fragment, 620);
}

function contractReviewNormalizeComparable(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .replace(/[.,;:]+$/g, "")
    .trim();
}

function contractReviewFormatDate(value) {
  const match = String(value || "").match(/(\d{1,2})[./](\d{1,2})[./](\d{2,4})/);
  if (!match) {
    return "";
  }
  const day = match[1].padStart(2, "0");
  const month = match[2].padStart(2, "0");
  const year = match[3].length === 2 ? `20${match[3]}` : match[3];
  return `${day}.${month}.${year}`;
}

function contractReviewDateToTime(value) {
  const formatted = contractReviewFormatDate(value);
  const match = formatted.match(/(\d{2})\.(\d{2})\.(\d{4})/);
  if (!match) {
    return Number.POSITIVE_INFINITY;
  }
  const time = Date.UTC(Number(match[3]), Number(match[2]) - 1, Number(match[1]));
  return Number.isFinite(time) ? time : Number.POSITIVE_INFINITY;
}

function contractReviewChronologyScore(values, fileRecord) {
  const startTime = contractReviewDateToTime(values.startDate);
  const endTime = contractReviewDateToTime(values.endDate);
  const fallback = Number(fileRecord?.score || fileRecord?.lastModified || 0);
  return {
    startTime,
    endTime,
    fallback,
    hasDates: Number.isFinite(startTime) || Number.isFinite(endTime)
  };
}

function contractReviewCompareChronology(left, right) {
  const leftScore = left.chronology || {};
  const rightScore = right.chronology || {};
  if (leftScore.hasDates !== rightScore.hasDates) {
    return leftScore.hasDates ? -1 : 1;
  }
  if (leftScore.startTime !== rightScore.startTime) {
    return leftScore.startTime - rightScore.startTime;
  }
  if (leftScore.endTime !== rightScore.endTime) {
    return leftScore.endTime - rightScore.endTime;
  }
  return (leftScore.fallback || 0) - (rightScore.fallback || 0)
    || left.file.name.localeCompare(right.file.name, "uk");
}

function contractReviewExtractDateRange(text) {
  const normalized = String(text || "").replace(/\s+/g, " ");
  const datePattern = "(\\d{1,2}[./]\\d{1,2}[./]\\d{2,4})";
  const rangePattern = new RegExp(`(?:з|від)\\s*${datePattern}\\s*(?:до|по|-)\\s*${datePattern}`, "i");
  const range = normalized.match(rangePattern);
  if (range) {
    return {
      startDate: contractReviewFormatDate(range[1]),
      endDate: contractReviewFormatDate(range[2])
    };
  }

  return {
    startDate: "",
    endDate: ""
  };
}

function contractReviewAmountPattern() {
  return /(\d{1,3}(?:[ \u00a0]\d{3})+(?:[,.]\d{1,2})?|\d{4,}(?:[,.]\d{1,2})?)\s*(грн|uah|usd|eur|євро|\$)?/i;
}

function contractReviewPercentPattern() {
  return /(\d{1,2}(?:[,.]\d{1,4})?)\s*%/i;
}

function contractReviewFindNearPattern(text, labels, pattern, maxWindow = 360) {
  const normalized = String(text || "").replace(/\s+/g, " ");
  const lowerText = normalized.toLowerCase();
  for (const label of labels) {
    const index = lowerText.indexOf(label.toLowerCase());
    if (index < 0) {
      continue;
    }
    const fragment = normalized.slice(index, index + maxWindow);
    const match = fragment.match(pattern);
    if (match) {
      const value = contractReviewCleanValue(match[0], 80);
      if (!contractReviewIsPlaceholderValue(value)) {
        return value;
      }
    }
  }
  return "";
}

function contractReviewClassifyProduct(text) {
  const lines = contractReviewTextLines(text);
  const titleAndSubject = [
    ...lines.slice(0, 30),
    ...contractReviewCoverageSection(lines, /предмет(?:ом)? договору/i, 14)
  ].join(" ").toLowerCase();

  if (/страхуван[а-яіїєґ]*\s+вантаж|cargo insurance/.test(titleAndSubject)) {
    return "Страхування вантажів";
  }
  if (/страхуван[а-яіїєґ]*.*відповідальност.*трет|страхуван[а-яіїєґ]*\s+(?:цивільної\s+)?відповідальності|third[- ]party liability insurance/.test(titleAndSubject)) {
    return "Страхування відповідальності перед третіми особами";
  }
  if (/будівельно[- ]монтажн|construction all risks|\bcar insurance\b/.test(titleAndSubject)) {
    return "Страхування будівельно-монтажних ризиків";
  }
  if (/монтажн[а-яіїєґ]*\s+ризик|erection all risks|\bear insurance\b/.test(titleAndSubject)) {
    return "Страхування монтажних ризиків";
  }
  if (/страхуван[а-яіїєґ]*.*машин.*полом|machinery breakdown insurance/.test(titleAndSubject)) {
    return "Страхування машин від поломок";
  }
  if (/страхуван[а-яіїєґ]*.*воєнн[а-яіїєґ]*\s+ризик|war risks insurance/.test(titleAndSubject)) {
    return "Страхування воєнних ризиків";
  }
  if (/страхуван[а-яіїєґ]*\s+майна|property insurance/.test(titleAndSubject)) {
    return "Страхування майна";
  }
  return "";
}

function contractReviewCoverageSection(lines, startPattern, maxLines = 30) {
  const startIndex = contractReviewFindLineIndex(lines, startPattern);
  if (startIndex < 0) {
    return [];
  }
  const result = [];
  for (let index = startIndex; index < Math.min(lines.length, startIndex + maxLines); index += 1) {
    const line = lines[index];
    if (
      index > startIndex
      && /^(?:виключення|не (?:є|визнаються?) страхов|не підлягають|не покриваються)/i.test(line)
    ) {
      break;
    }
    result.push(line);
  }
  return result;
}

function contractReviewClassifyRisks(text) {
  const lines = contractReviewTextLines(text);
  const titleLines = lines.slice(0, 30);
  const subjectLines = contractReviewCoverageSection(lines, /предмет(?:ом)? договору/i, 16);
  const riskLines = contractReviewCoverageSection(
    lines,
    /^(?:\d+(?:\.\d+)*\.?\s*)?(?:страхові ризики|перелік страхових (?:ризиків|випадків)|страховими випадками)/i,
    45
  );
  const titleAndSubject = [...titleLines, ...subjectLines].join(" ").toLowerCase();
  const affirmativeCoverage = [...subjectLines, ...riskLines]
    .filter((line) => !/^(?:виключення|не (?:є|визнаються?) страхов|не підлягають|не покриваються)/i.test(line))
    .join(" ")
    .toLowerCase();
  const propertyEvidence = `${titleAndSubject} ${affirmativeCoverage}`;
  const risks = [];
  const hasProperty = /страхуван[а-яіїєґ]*\s+майна|property insurance|застрахован[а-яіїєґ]*\s+майн/.test(propertyEvidence);
  const allRisks = /all risks|від усіх ризик|від всіх ризик|будь-як[а-яіїєґ]*\s+випадков[а-яіїєґ]*\s+(?:і|та)\s+непередбач[а-яіїєґ]*\s+зовнішн[а-яіїєґ]*\s+фізичн[а-яіїєґ]*\s+вплив/.test(affirmativeCoverage);
  const namedPerils = /named perils|назван[а-яіїєґ]*\s+ризик|пойменован[а-яіїєґ]*\s+ризик|перелічен[а-яіїєґ]*\s+ризик/.test(affirmativeCoverage)
    || (!allRisks && /(?:перелік страхових ризиків|страховими ризиками (?:є|визнаються)\s*:)/.test(affirmativeCoverage));
  if (hasProperty && allRisks) {
    risks.push("PD all risks");
  } else if (hasProperty && namedPerils) {
    risks.push("PD named perils");
  } else if (hasProperty) {
    risks.push("PD");
  }
  if (/перерв[а-яіїєґ]*\s+у\s+господарськ[а-яіїєґ]*\s+діяльност|business interruption/.test(`${titleAndSubject} ${affirmativeCoverage}`)) {
    risks.push("business interruption");
  }
  if (/страхуван[а-яіїєґ]*.*відповідальност.*трет|страхуван[а-яіїєґ]*\s+(?:цивільної\s+)?відповідальності|third[- ]party liability insurance/.test(titleAndSubject)) {
    risks.push("TPL");
  }
  if (/страхуван[а-яіїєґ]*\s+вантаж|cargo insurance/.test(titleAndSubject)) {
    risks.push("cargo");
  }
  if (/страхуван[а-яіїєґ]*.*воєнн[а-яіїєґ]*\s+ризик|war risks insurance/.test(`${titleAndSubject} ${affirmativeCoverage}`)) {
    risks.push("WAR");
  }
  if (/будівельно[- ]монтажн|construction all risks|\bcar insurance\b/.test(titleAndSubject)) {
    risks.push("CAR");
  }
  if (/монтажн[а-яіїєґ]*\s+ризик|erection all risks|\bear insurance\b/.test(titleAndSubject)) {
    risks.push("EAR");
  }
  if (/страхуван[а-яіїєґ]*.*машин.*полом|machinery breakdown insurance/.test(titleAndSubject)) {
    risks.push("MB");
  }
  return [...new Set(risks)].join(", ");
}

function contractReviewExtractValuationBasis(text) {
  const lines = contractReviewTextLines(text);
  for (const line of lines) {
    if (!/^(?:\d+(?:\.\d+)*\.?\s*)?(?:базис оцінки|страхування .*?(?:здійснюється|проводиться) на базі|страхова сума .*?(?:визначена|встановлена) .*?варт)/i.test(line)) {
      continue;
    }
    if (/відновлювальн|replacement/i.test(line)) {
      return "ВВ";
    }
    if (/дійсн[а-яіїєґ]*\s+варт|поточн[а-яіїєґ]*\s+варт|ринков[а-яіїєґ]*\s+варт|actual cash/i.test(line)) {
      return "ДВ";
    }
    if (/балансов/i.test(line)) {
      return "Балансова вартість";
    }
  }
  return "";
}

function contractReviewExtractValues(text) {
  const lines = contractReviewTextLines(text);
  const extractedDateRange = contractReviewExtractCoverageDatesFromLines(lines) || contractReviewExtractDateRange(text);
  const extractedStartTime = contractReviewDateToTime(extractedDateRange.startDate);
  const extractedEndTime = contractReviewDateToTime(extractedDateRange.endDate);
  const dateRangeIsValid =
    !Number.isFinite(extractedStartTime)
    || !Number.isFinite(extractedEndTime)
    || extractedEndTime > extractedStartTime;
  const dateRange = dateRangeIsValid ? extractedDateRange : { startDate: "", endDate: "" };
  const financialValues = contractReviewExtractFinancialValues(lines);
  const insurer = contractReviewExtractInsurer(lines)
    || contractReviewNormalizePartyName(contractReviewFindLineValue(
      lines,
      ["страховик", "страхова компанія"],
      { maxLength: 180, validate: contractReviewLineLooksLikePartyValue }
    ));
  const insured = contractReviewExtractInsured(lines)
    || contractReviewNormalizePartyName(contractReviewFindLineValue(
      lines,
      ["страхувальник", "застрахована особа"],
      { maxLength: 180, validate: contractReviewLineLooksLikePartyValue }
    ));
  const contractNumber = contractReviewFindNearPattern(text, ["договір страхування", "договір", "поліс"], /(?:№|N|No\.?)\s*([A-Za-zА-Яа-яІіЇїЄєҐґ0-9/.\-]+)/i, 160)
    || contractReviewFindLineValue(lines, ["№ договору", "номер договору"], { maxLength: 80 });
  const addressValidator = (value) =>
    /(?:м\.|місто|смт|село|вул\.|вулиц|просп|пров\.|обл\.|область|р-н|район|с\/р|сільрад|комплекс будівель)/i.test(value)
    && !/^(?:territory of insurance|insurance territory)$/i.test(value);
  const address = contractReviewExtractInsuredAddress(lines)
    || contractReviewFindLineValue(lines, [
      "адреса дії договору",
      "місце дії договору",
      "місце страхування",
      "територія страхування",
      "місцезнаходження майна",
      "адреса майна"
    ], { maxLength: 260, lookahead: 12, validate: addressValidator });
  const product = contractReviewExtractProductName(lines) || contractReviewClassifyProduct(text);
  const risks = contractReviewClassifyRisks(text);
  const beneficiary = contractReviewExtractBeneficiary(lines)
    || contractReviewNormalizePartyName(contractReviewFindLineValue(
      lines,
      ["вигодонабувач", "вигодоодержувач"],
      { maxLength: 180, validate: contractReviewLineLooksLikePartyValue }
    ));

  return {
    insured,
    address,
    insurer,
    contractNumber,
    intermediaryClause: contractReviewExtractIntermediaryClause(lines),
    product,
    beneficiary,
    valuationBasis: contractReviewExtractValuationBasis(text),
    risks,
    startDate: dateRange.startDate,
    endDate: dateRange.endDate,
    deductible: financialValues.deductible,
    sumInsured: financialValues.sumInsured,
    rate: financialValues.rate,
    limits: [financialValues.coverageLimits, contractReviewExtractLimits(lines)].filter(Boolean).join("; "),
    premium: financialValues.premium
  };
}

function contractReviewCompareField(row, previousValue, renewalValue) {
  if (!previousValue && !renewalValue) {
    return "Не знайдено автоматично";
  }
  if (!previousValue || !renewalValue) {
    return "Перевірити";
  }
  if (contractReviewNormalizeComparable(previousValue) === contractReviewNormalizeComparable(renewalValue)) {
    return "Без змін";
  }
  return "Змінено";
}

function addContractReviewFiles(files) {
  const incoming = Array.from(files || []).filter(isContractReviewFile);
  const existingIds = new Set(contractReviewFiles.map((file) => file.id));
  const nextFiles = incoming
    .map((file, index) => ({
      id: contractReviewFileId(file, index),
      name: file.name,
      size: file.size,
      type: file.type || contractReviewFileExtension(file.name).replace(".", "").toUpperCase(),
      lastModified: file.lastModified || Date.now(),
      file,
      score: contractReviewScore(file),
      readStatus: contractReviewInitialStatus(file)
    }))
    .filter((file) => !existingIds.has(file.id));

  if (!nextFiles.length) {
    contractReviewCopyMessage = incoming.length ? "Ці файли вже додано." : "Підтримуються DOC, DOCX, PDF, XLS, XLSX.";
    renderContractReview();
    return;
  }

  contractReviewFiles = [...contractReviewFiles, ...nextFiles].sort((a, b) => a.score - b.score || a.name.localeCompare(b.name, "uk"));
  contractReviewResult = null;
  contractReviewCopyMessage = "";
  renderContractReview();
}

function removeContractReviewFile(fileId) {
  contractReviewFiles = contractReviewFiles.filter((file) => file.id !== fileId);
  contractReviewResult = null;
  contractReviewCopyMessage = "";
  renderContractReview();
}

function resetContractReviewFiles() {
  contractReviewFiles = [];
  contractReviewResult = null;
  contractReviewCopyMessage = "";
  renderContractReview();
}

async function buildContractReviewResult() {
  if (contractReviewFiles.length < 2) {
    contractReviewCopyMessage = "Додай щонайменше два договори.";
    renderContractReview();
    return;
  }

  contractReviewBusy = true;
  contractReviewCopyMessage = "Читаю договори...";
  renderContractReview();

  const sorted = [...contractReviewFiles].sort((a, b) => a.score - b.score || a.name.localeCompare(b.name, "uk"));
  try {
    const enriched = await Promise.all(sorted.map(async (fileRecord) => {
      try {
        const extracted = await contractReviewReadText(fileRecord);
        return {
          ...fileRecord,
          text: extracted.text,
          readStatus: extracted.status
        };
      } catch (error) {
        return {
          ...fileRecord,
          text: "",
          readStatus: error?.message || "Файл не вдалося прочитати"
        };
      }
    }));

    contractReviewFiles = enriched;
    const readableFiles = enriched.filter((file) => file.text);
    if (readableFiles.length < 2) {
      const previousCandidate = readableFiles[0] || enriched[0];
      const renewalCandidate = enriched.find((file) => file.id !== previousCandidate?.id) || enriched[enriched.length - 1] || previousCandidate;
      contractReviewResult = {
        previous: previousCandidate,
        renewal: renewalCandidate,
        supporting: enriched.filter((file) => file.id !== previousCandidate?.id && file.id !== renewalCandidate?.id),
        rows: [],
        foundCount: 0,
        readableCount: readableFiles.length,
        blocked: true,
        statuses: enriched.map((file) => `${file.name}: ${file.readStatus}`),
        createdAt: new Date().toISOString()
      };
      contractReviewCopyMessage = readableFiles.length
        ? "Порівняння не запущено: прочитано лише один договір. Додай другий DOC, DOCX або текстовий PDF."
        : "Порівняння не запущено: Anodos не зміг прочитати текст договорів. Для автоматичного аналізу потрібні два DOC, DOCX або текстові PDF.";
      contractReviewBusy = false;
      renderContractReview();
      return;
    }

    const analyzedFiles = readableFiles.map((file) => {
      const values = contractReviewExtractValues(file.text);
      return {
        file,
        values,
        chronology: contractReviewChronologyScore(values, file)
      };
    }).sort(contractReviewCompareChronology);
    const previousRecord = analyzedFiles[0];
    const renewalRecord = analyzedFiles[analyzedFiles.length - 1];
    const previous = previousRecord.file;
    const renewal = renewalRecord.file;
    const selectedFileIds = new Set([previous.id, renewal.id]);
    const supporting = enriched.filter((file) => !selectedFileIds.has(file.id));
    const orderedFiles = [
      previous,
      ...enriched.filter((file) => !selectedFileIds.has(file.id)),
      renewal
    ];
    contractReviewFiles = orderedFiles;
    const previousValues = previousRecord.values;
    const renewalValues = renewalRecord.values;
    const rows = contractReviewFields.map((field) => {
      const previousValue = previousValues[field.key] || "";
      const renewalValue = renewalValues[field.key] || "";
      return {
        ...field,
        previousValue,
        renewalValue,
        control: contractReviewCompareField(field, previousValue, renewalValue)
      };
    });
    const foundCount = rows.filter((row) => row.previousValue || row.renewalValue).length;
    const readableCount = enriched.filter((file) => file.text).length;

    contractReviewResult = {
      previous,
      renewal,
      supporting,
      rows,
      foundCount,
      readableCount,
      statuses: enriched.map((file) => `${file.name}: ${file.readStatus}`),
      createdAt: new Date().toISOString()
    };
    contractReviewCopyMessage = foundCount
      ? `Порівняння сформовано: знайдено ${foundCount} з ${contractReviewFields.length} параметрів.`
      : readableCount
        ? "Документи прочитано, але параметри не знайдені автоматично. Перевір формат договору."
        : "Не вдалося прочитати текст договорів. Для автоматичного аналізу завантаж DOC, DOCX або текстовий PDF.";
  } finally {
    contractReviewBusy = false;
  }
  renderContractReview();
}

function contractReviewTableTsv() {
  if (!contractReviewResult) {
    return "";
  }

  const header = [
    "Параметр",
    `Попередній договір: ${contractReviewResult.previous.name}`,
    `Договір оновлення: ${contractReviewResult.renewal.name}`,
    "Контроль"
  ];
  const rows = contractReviewResult.rows.map((row) => [
    row.label,
    row.previousValue,
    row.renewalValue,
    row.control
  ]);
  return [header, ...rows].map((row) => row.map(escapeTsv).join("\t")).join("\n");
}

function contractReviewTableHtml() {
  if (!contractReviewResult) {
    return "";
  }

  const rows = contractReviewResult.rows.map((row) => `
    <tr>
      <th>${escapeHtml(row.label)}</th>
      <td>${escapeHtml(row.previousValue)}</td>
      <td>${escapeHtml(row.renewalValue)}</td>
      <td>${escapeHtml(row.control)}</td>
    </tr>
  `).join("");

  return `
    <table>
      <thead>
        <tr>
          <th>Параметр</th>
          <th>Попередній договір: ${escapeHtml(contractReviewResult.previous.name)}</th>
          <th>Договір оновлення: ${escapeHtml(contractReviewResult.renewal.name)}</th>
          <th>Контроль</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

async function copyContractReviewTable() {
  if (!contractReviewResult) {
    contractReviewCopyMessage = "Спочатку сформуй таблицю.";
    renderContractReview();
    return;
  }

  const tsv = contractReviewTableTsv();
  const html = contractReviewTableHtml();
  try {
    if (navigator.clipboard?.write && window.ClipboardItem) {
      await navigator.clipboard.write([
        new ClipboardItem({
          "text/html": new Blob([html], { type: "text/html" }),
          "text/plain": new Blob([tsv], { type: "text/plain" })
        })
      ]);
    } else {
      await navigator.clipboard.writeText(tsv);
    }
    contractReviewCopyMessage = "Таблицю скопійовано.";
  } catch {
    contractReviewCopyMessage = "Не вдалося скопіювати автоматично. Виділи таблицю вручну.";
  }
  renderContractReview();
}

function quizReportId(scope, lessonId, questionIndex) {
  return `${scope}:${lessonId}:${questionIndex}`;
}

function renderAccuracyReportForm(reportId) {
  return `
    <div class="accuracy-report-form" data-accuracy-report-form="${escapeHtml(reportId)}" data-active-report-form>
      <label>
        <span>Що саме потребує перевірки?</span>
        <textarea name="accuracyReportNote" rows="3" placeholder="Наприклад: варіант B звучить надто широко; у договорі треба перевірити виняток або субліміт.">${escapeHtml(accuracyReportDrafts[reportId] || "")}</textarea>
      </label>
      ${accuracyReportErrorId === reportId ? `<p class="accuracy-report-error">Додайте короткий зміст зауваження.</p>` : ""}
      <div class="accuracy-report-actions">
        <button class="secondary-action" type="button" data-save-accuracy-report>Зберегти зауваження</button>
        <button class="ghost-text-button" type="button" data-cancel-accuracy-report>Скасувати</button>
      </div>
    </div>
  `;
}

function renderQuestionTrustBlock(scope, item, question, questionIndex) {
  const reportId = quizReportId(scope, item.id, questionIndex);
  const localReportCount = accuracyReports.filter((report) => report.reportId === reportId).length;
  return `
    <div class="question-report-line">
      <button class="trust-report-button" type="button" data-report-issue="${escapeHtml(reportId)}">
        Повідомити про неточність
      </button>
      ${localReportCount ? `<span class="accuracy-report-saved">є локальне зауваження</span>` : ""}
      ${accuracyReportSavedId === reportId ? `<span class="accuracy-report-saved">збережено локально</span>` : ""}
    </div>
    ${activeAccuracyReportId === reportId ? renderAccuracyReportForm(reportId) : ""}
  `;
}

function saveAccuracyReport(reportId, note) {
  const [scope, lessonId, questionIndexText] = reportId.split(":");
  const questionIndex = Number(questionIndexText);
  const item = getLesson(lessonId);
  const test = scope === "law" ? item.lawTests : item;
  const question = test?.quiz?.[questionIndex];
  if (!item || !question) {
    return false;
  }

  const selected = quizAnswers[questionIndex];
  const user = currentUser();
  accuracyReports.unshift({
    id: `accuracy-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
    reportId,
    scope,
    lessonId: item.id,
    lessonTitle: item.title,
    testTitle: test.title || item.quizTitle || item.title,
    questionIndex,
    question: question.question,
    correctAnswer: question.options[question.answer],
    selectedAnswer: selected === null || selected === undefined ? "" : question.options[selected] || "",
    note,
    status: "new",
    createdAt: new Date().toISOString(),
    userName: user?.fullName || "",
    userEmail: user?.email || ""
  });
  writeJson(accuracyReportsKey, accuracyReports);
  return true;
}

function exportAccuracyReports() {
  const rows = [[
    "Дата",
    "Модуль",
    "Тест",
    "Питання",
    "Правильна відповідь",
    "Обрана відповідь",
    "Зауваження",
    "Користувач",
    "Email",
    "Статус"
  ]];

  accuracyReports.forEach((report) => {
    rows.push([
      report.createdAt || "",
      report.lessonTitle || "",
      report.testTitle || "",
      report.question || "",
      report.correctAnswer || "",
      report.selectedAnswer || "",
      report.note || "",
      report.userName || "",
      report.userEmail || "",
      report.status || "new"
    ]);
  });

  const csv = rows.map((row) => row.map(escapeCsv).join(",")).join("\n");
  downloadTextFile(`anodos-accuracy-reports-${Date.now()}.csv`, csv, "text/csv;charset=utf-8");
}

function totalProgress() {
  const scored = lessons.map((item) => moduleProgress(item));
  return Math.round(scored.reduce((sum, value) => sum + value, 0) / scored.length);
}

function moduleProgress(item) {
  const stored = progress[item.id];
  if (currentUser()) {
    if (!stored) {
      return 0;
    }
    return Math.max(stored.score || 0, stored.done ? 100 : 0);
  }
  if (!stored) {
    return item.progress;
  }
  return Math.max(item.progress, stored.score || 0, stored.done ? 100 : 0);
}

function moduleProgressFromStore(item, storedProgress = {}) {
  const stored = storedProgress[item.id];
  if (!stored) {
    return 0;
  }
  return Math.max(stored.score || 0, stored.done ? 100 : 0);
}

function totalProgressFromStore(storedProgress = {}) {
  if (!lessons.length) {
    return 0;
  }
  const scored = lessons.map((item) => moduleProgressFromStore(item, storedProgress));
  return Math.round(scored.reduce((sum, value) => sum + value, 0) / lessons.length);
}

function syncConfigured() {
  return Boolean(
    syncConfig.enabled &&
    syncConfig.provider === "supabase" &&
    syncConfig.supabaseUrl &&
    syncConfig.supabaseAnonKey &&
    syncConfig.table
  );
}

function syncModeLabel() {
  if (!syncConfig.enabled) {
    return "локальний режим";
  }
  if (syncConfigured()) {
    return "центральна база активна";
  }
  return "потрібна конфігурація бази";
}

function setSyncStatus(state, message) {
  syncStatus = {
    state,
    message,
    lastSyncAt: new Date().toISOString()
  };
}

function supabaseEndpoint(query = "") {
  const baseUrl = String(syncConfig.supabaseUrl || "").replace(/\/$/, "");
  const table = encodeURIComponent(syncConfig.table);
  return `${baseUrl}/rest/v1/${table}${query}`;
}

function supabaseHeaders(extra = {}) {
  return {
    apikey: syncConfig.supabaseAnonKey,
    Authorization: `Bearer ${syncConfig.supabaseAnonKey}`,
    "Content-Type": "application/json",
    ...extra
  };
}

function progressPayloadForUser(user) {
  const storedProgress = progressByUser[user.id] || (user.id === currentUserId ? progress : {});
  return {
    id: user.id,
    full_name: user.fullName || "",
    email: normalizeEmail(user.email),
    registered_at: user.registeredAt || new Date().toISOString(),
    last_seen_at: user.lastSeenAt || new Date().toISOString(),
    total_progress: totalProgressFromStore(storedProgress),
    progress: storedProgress,
    updated_at: new Date().toISOString()
  };
}

function normalizeCentralParticipant(row) {
  const storedProgress = row.progress && typeof row.progress === "object" ? row.progress : {};
  return {
    id: row.id || normalizeEmail(row.email),
    fullName: row.full_name || row.fullName || "Співробітник",
    email: normalizeEmail(row.email),
    registeredAt: row.registered_at || row.registeredAt || "",
    lastSeenAt: row.last_seen_at || row.lastSeenAt || "",
    updatedAt: row.updated_at || row.updatedAt || "",
    totalProgress: Number(row.total_progress ?? row.totalProgress ?? totalProgressFromStore(storedProgress)) || 0,
    progress: storedProgress,
    source: "central"
  };
}

function localParticipantRows() {
  return authorizedUsers().map((user) => {
    const storedProgress = progressByUser[user.id] || (user.id === currentUserId ? progress : {});
    return {
      id: user.id,
      fullName: user.fullName || "Співробітник",
      email: normalizeEmail(user.email),
      registeredAt: user.registeredAt || "",
      lastSeenAt: user.lastSeenAt || "",
      updatedAt: storedProgress.updatedAt || user.lastSeenAt || user.registeredAt || "",
      totalProgress: totalProgressFromStore(storedProgress),
      progress: storedProgress,
      source: "local"
    };
  });
}

function participantRegistryRows() {
  const byEmail = new Map();

  centralParticipants.map(normalizeCentralParticipant).forEach((participant) => {
    if (participant.email) {
      byEmail.set(participant.email, participant);
    }
  });

  localParticipantRows().forEach((participant) => {
    const previous = byEmail.get(participant.email);
    if (!previous) {
      byEmail.set(participant.email, participant);
      return;
    }
    const centralTime = Date.parse(previous.updatedAt || previous.lastSeenAt || previous.registeredAt || 0) || 0;
    const localTime = Date.parse(participant.updatedAt || participant.lastSeenAt || participant.registeredAt || 0) || 0;
    byEmail.set(participant.email, {
      ...(localTime >= centralTime ? previous : participant),
      ...(localTime >= centralTime ? participant : previous),
      source: "mixed"
    });
  });

  return Array.from(byEmail.values()).sort((first, second) => {
    const secondTime = Date.parse(second.updatedAt || second.lastSeenAt || second.registeredAt || 0) || 0;
    const firstTime = Date.parse(first.updatedAt || first.lastSeenAt || first.registeredAt || 0) || 0;
    return secondTime - firstTime || first.fullName.localeCompare(second.fullName, "uk");
  });
}

function formatShortDate(value) {
  if (!value) {
    return "—";
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "—";
  }
  return new Intl.DateTimeFormat("uk-UA", {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
  }).format(date);
}

async function pushParticipantToCentral(user) {
  if (!syncConfigured() || !isAuthorizedUser(user)) {
    return false;
  }

  const payload = progressPayloadForUser(user);
  const response = await fetch(supabaseEndpoint("?on_conflict=email"), {
    method: "POST",
    headers: supabaseHeaders({ Prefer: "resolution=merge-duplicates,return=minimal" }),
    body: JSON.stringify([payload])
  });

  if (!response.ok) {
    throw new Error(`Сервер повернув ${response.status}`);
  }

  return true;
}

async function syncCurrentParticipant(reason = "manual") {
  const user = currentUser();
  if (!user) {
    return false;
  }
  if (!syncConfigured()) {
    setSyncStatus("disabled", "Центральну базу ще не підключено.");
    return false;
  }

  try {
    await pushParticipantToCentral(user);
    setSyncStatus("ok", reason === "progress" ? "Прогрес відправлено в центральну базу." : "Профіль синхронізовано з центральною базою.");
    return true;
  } catch (error) {
    setSyncStatus("error", `Не вдалося синхронізувати: ${error.message}`);
    return false;
  }
}

function syncExistingParticipantOnStartup() {
  const user = currentUser();
  if (!user || !syncConfigured()) {
    return;
  }

  user.lastSeenAt = new Date().toISOString();
  saveRegisteredUsers();
  void syncCurrentParticipant("startup");
}

async function refreshCentralParticipants({ renderAfter = true } = {}) {
  if (!syncConfigured()) {
    setSyncStatus("disabled", "Центральну базу ще не підключено.");
    if (renderAfter) {
      render();
    }
    return false;
  }

  try {
    const response = await fetch(supabaseEndpoint("?select=*&order=updated_at.desc"), {
      headers: supabaseHeaders()
    });
    if (!response.ok) {
      throw new Error(`Сервер повернув ${response.status}`);
    }
    const rows = await response.json();
    centralParticipants = Array.isArray(rows) ? rows : [];
    writeJson(centralParticipantsKey, centralParticipants);
    setSyncStatus("ok", `Оновлено ${centralParticipants.length} записів з центральної бази.`);
    if (renderAfter) {
      render();
    }
    return true;
  } catch (error) {
    setSyncStatus("error", `Не вдалося отримати центральний реєстр: ${error.message}`);
    if (renderAfter) {
      render();
    }
    return false;
  }
}

function stopPresentation() {
  presentationPlaying = false;
  if (presentationTimer) {
    window.clearInterval(presentationTimer);
    presentationTimer = null;
  }
}

function applyRouteState(nextRoute, lessonId = activeLessonId) {
  if (nextRoute !== "presentation") {
    stopPresentation();
  }
  if (nextRoute === "presentation" && (route !== "presentation" || lessonId !== activeLessonId)) {
    activeSlideIndex = 0;
  }
  if (nextRoute !== "contract" && !(nextRoute === "module-section" && activeModuleSectionId === "contracts") && nextRoute !== "contract-auth") {
    contractAccessGranted = false;
    pendingContractTemplateId = "";
    contractPasswordError = "";
  }
  route = nextRoute;
  activeLessonId = lessonId;
  quizAnswers = {};
  quizResult = null;
  render();
  window.scrollTo(0, 0);
}

function setRoute(nextRoute, lessonId = activeLessonId) {
  const normalizedLessonId = lessonId || activeLessonId;
  const isSamePendingRoute = pendingRoute === nextRoute && pendingLessonId === normalizedLessonId;
  const isSameCurrentRoute = !pendingRoute && route === nextRoute && activeLessonId === normalizedLessonId;

  if (isSamePendingRoute) {
    return;
  }

  if (isSameCurrentRoute) {
    window.scrollTo(0, 0);
    return;
  }

  window.clearTimeout(routeTransitionTimer);
  window.clearTimeout(routeTransitionInTimer);
  pendingRoute = nextRoute;
  pendingLessonId = normalizedLessonId;

  if (prefersReducedMotion) {
    screen.classList.remove("screen-transition-out", "screen-transition-in");
    body.classList.remove("route-is-changing");
    applyRouteState(nextRoute, normalizedLessonId);
    pendingRoute = "";
    pendingLessonId = "";
    return;
  }

  screen.classList.remove("screen-transition-in");
  screen.classList.add("screen-transition-out");
  body.classList.add("route-is-changing");

  routeTransitionTimer = window.setTimeout(() => {
    applyRouteState(nextRoute, normalizedLessonId);
    screen.classList.remove("screen-transition-out");
    screen.classList.add("screen-transition-in");
    body.classList.remove("route-is-changing");
    pendingRoute = "";
    pendingLessonId = "";

    routeTransitionInTimer = window.setTimeout(() => {
      screen.classList.remove("screen-transition-in");
    }, 240);
  }, 65);
}

function getLesson(id = activeLessonId) {
  return lessons.find((item) => item.id === id) || lessons[0];
}

function allContractTemplates() {
  return lessons.flatMap((item) =>
    (item.contractTemplates || []).map((template) => ({
      ...template,
      lessonId: item.id,
      lessonIndex: item.index,
      lessonTitle: item.title
    }))
  );
}

function getContractTemplate(id = activeContractTemplateId) {
  const templates = allContractTemplates();
  return templates.find((template) => template.id === id) || templates[0] || null;
}

function clampContractZoom(value) {
  const next = Number(value);
  if (!Number.isFinite(next)) {
    return 1;
  }
  return Math.min(Math.max(next, 1), 2.8);
}

function contractZoomPercent() {
  return `${Math.round(contractZoom * 10000) / 100}%`;
}

function contractZoomLabel() {
  return `${Math.round(contractZoom * 100)}%`;
}

function applyContractZoom() {
  const panel = document.querySelector(".contract-viewer-panel");
  if (!panel) {
    return;
  }

  panel.style.setProperty("--contract-page-width", contractZoomPercent());
  const zoomValue = panel.querySelector("[data-contract-zoom-value]");
  if (zoomValue) {
    zoomValue.textContent = contractZoomLabel();
  }
}

function setContractZoom(value) {
  contractZoom = clampContractZoom(value);
  applyContractZoom();
}

function resetContractZoom() {
  contractPinchStartDistance = 0;
  contractPinchStartZoom = 1;
  contractGestureStartZoom = 1;
  setContractZoom(1);
}

function touchDistance(touches) {
  if (!touches || touches.length < 2) {
    return 0;
  }
  const first = touches[0];
  const second = touches[1];
  return Math.hypot(second.clientX - first.clientX, second.clientY - first.clientY);
}

function openContractTemplate(templateId) {
  const template = getContractTemplate(templateId);
  if (!template) {
    return;
  }

  if (!contractAccessGranted) {
    pendingContractTemplateId = template.id;
    activeModuleSectionId = "contracts";
    contractPasswordError = "";
    setRoute("contract-auth", template.lessonId || "property");
    return;
  }

  activeContractTemplateId = template.id;
  resetContractZoom();
  setRoute("contract", template.lessonId || "property");

  window.setTimeout(() => {
    if (route === "contract" && activeContractTemplateId === template.id) {
      return;
    }
    pendingRoute = "";
    pendingLessonId = "";
    body.classList.remove("route-is-changing");
    screen.classList.remove("screen-transition-out", "screen-transition-in");
    applyRouteState("contract", template.lessonId || "property");
  }, 160);
}

function draftFor(id) {
  return editorDrafts[id] || {};
}

function render() {
  const user = currentUser();
  renderSpaceShell();
  if (!isAuthorizedUser(user)) {
    body.dataset.route = "registration";
    if (currentUserId) {
      clearCurrentUser();
    }
    body.classList.add("registration-mode");
    setCompassOpen(false);
    document.querySelectorAll(".nav-item").forEach((button) => {
      button.classList.remove("nav-item-active");
    });
    renderRegistration();
    return;
  }

  body.classList.remove("registration-mode");
  body.dataset.route = route;
  body.classList.toggle("scenario-search-active", activeSpace === "products" && route === "home" && scenarioSearchTerm.trim().length > 0);
  renderCompass();

  if (route === "module") {
    renderModule(getLesson());
    return;
  }

  if (route === "module-section") {
    renderModuleSection(getLesson(), activeModuleSectionId);
    return;
  }

  if (route === "contract-auth") {
    renderContractAccess(getLesson());
    return;
  }

  if (route === "quiz") {
    renderQuiz(getLesson());
    return;
  }

  if (route === "law-quiz") {
    renderLawQuiz(getLesson());
    return;
  }

  if (route === "presentation") {
    renderPresentation(getLesson());
    return;
  }

  if (route === "contract") {
    renderContractTemplateViewer(getContractTemplate());
    return;
  }

  if (route === "sources") {
    renderSources();
    return;
  }

  if (route === "law") {
    renderLaw();
    return;
  }

  if (route === "munich") {
    renderMunichClauses();
    return;
  }

  if (route === "glossary") {
    renderGlossary();
    return;
  }

  if (route === "editor") {
    renderEditor(getLesson());
    return;
  }

  if (route === "progress") {
    renderProgress();
    return;
  }

  if (route === "contract-review") {
    renderContractReview();
    return;
  }

  renderHome();
}

function renderContractReviewFile(file, index) {
  const canRead = contractReviewCanAutoReadFile(file);
  const role = contractReviewFiles.length < 2
    ? ""
    : index === 0
      ? "Попередній"
      : index === contractReviewFiles.length - 1
        ? "Оновлення"
        : "Супровідний";
  return `
    <li class="contract-review-file ${canRead ? "contract-review-file-ready" : "contract-review-file-blocked"}">
      <span>
        <strong>${escapeHtml(file.name)}</strong>
        <small>${escapeHtml(role || "Документ")} · ${escapeHtml(contractReviewFormatSize(file.size))}${file.readStatus ? ` · ${escapeHtml(file.readStatus)}` : ""}</small>
      </span>
      <button type="button" data-remove-contract-review-file="${escapeHtml(file.id)}" aria-label="Прибрати файл ${escapeHtml(file.name)}">×</button>
    </li>
  `;
}

function renderContractReviewTable() {
  if (!contractReviewResult) {
    return "";
  }

  if (!contractReviewResult.foundCount) {
    const title = contractReviewResult.blocked ? "Порівняння не запущено" : "Дані не витягнулися";
    const explanation = contractReviewResult.blocked
      ? "Anodos не формує порожню таблицю, якщо прочитано менше двох договорів. Додай два договори у DOC, DOCX або PDF з текстовим шаром."
      : "Anodos не буде показувати порожню таблицю як результат. Перевір формат файлів і завантаж заповнені договори у форматі DOC, DOCX або PDF з текстовим шаром.";
    return `
      <section class="contract-review-result contract-review-diagnostic">
        <header class="contract-review-result-head">
          <div>
            <p class="eyebrow">Діагностика</p>
            <h2>${escapeHtml(title)}</h2>
          </div>
        </header>
        <p class="contract-review-note">${escapeHtml(explanation)}</p>
        <ul class="contract-review-diagnostic-list">
          ${contractReviewResult.statuses.map((status) => `<li>${escapeHtml(status)}</li>`).join("")}
        </ul>
        <p class="contract-review-note">Якщо PDF є сканом, його треба спочатку розпізнати OCR. Для старих DOC Anodos читає текст напряму, але якість залежить від структури файлу.</p>
      </section>
    `;
  }

  return `
    <section class="contract-review-result">
      <header class="contract-review-result-head">
        <div>
          <p class="eyebrow">Результат</p>
          <h2>Порівняльна таблиця</h2>
        </div>
        <button class="primary-action" type="button" data-copy-contract-review>Копіювати таблицю</button>
      </header>
      <div class="contract-review-pair">
        <article>
          <span>Попередній договір</span>
          <strong>${escapeHtml(contractReviewResult.previous.name)}</strong>
        </article>
        <article>
          <span>Договір оновлення</span>
          <strong>${escapeHtml(contractReviewResult.renewal.name)}</strong>
        </article>
      </div>
      ${contractReviewResult.supporting.length ? `
        <p class="contract-review-supporting">Супровідні файли: ${contractReviewResult.supporting.map((file) => escapeHtml(file.name)).join("; ")}</p>
      ` : ""}
      <div class="contract-review-table-wrap">
        <table class="contract-review-table">
          <thead>
            <tr>
              <th>Параметр</th>
              <th>Попередній договір</th>
              <th>Договір оновлення</th>
              <th>Контроль</th>
            </tr>
          </thead>
          <tbody>
            ${contractReviewResult.rows.map((row) => `
              <tr>
                <th>${escapeHtml(row.label)}</th>
                <td>${escapeHtml(row.previousValue)}</td>
                <td>${escapeHtml(row.renewalValue)}</td>
                <td>${escapeHtml(row.control)}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    </section>
  `;
}

function renderContractReview() {
  const readyFilesCount = contractReviewFiles.filter(contractReviewCanAutoReadFile).length;
  const canCompare = readyFilesCount >= 2 && !contractReviewBusy;
  const compareButtonText = contractReviewBusy
    ? "Порівнюю..."
    : contractReviewFiles.length < 2
      ? "Додай два договори"
      : readyFilesCount < 2
        ? "Потрібні читабельні файли"
        : "Порівняти";
  const readinessClass = readyFilesCount >= 2 ? "contract-review-readiness" : "contract-review-readiness contract-review-readiness-warning";
  const readinessText = contractReviewFiles.length
    ? readyFilesCount >= 2
      ? `Готові до аналізу: ${readyFilesCount} з ${contractReviewFiles.length}.`
      : `Готові до аналізу: ${readyFilesCount} з ${contractReviewFiles.length}. Для порівняння потрібні щонайменше два читабельні договори.`
    : "";
  screen.innerHTML = `
    <section class="contract-review-workspace">
      <header class="contract-review-head">
        <button class="module-back" type="button" data-route="home" aria-label="Назад до продуктів">←</button>
        <div>
          <p class="eyebrow">Anodos · desktop</p>
          <h1>Порівняння договорів</h1>
          <p class="hero-copy">Завантаж два або більше договорів. Система визначить попередній і новий документ та сформує таблицю для копіювання.</p>
        </div>
      </header>

      <section class="contract-review-dropzone" data-contract-review-dropzone>
        <input id="contractReviewInput" type="file" multiple accept=".doc,.docx,.pdf,.xls,.xlsx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" />
        <label for="contractReviewInput">
          <span>Перетягни договори сюди</span>
          <strong>або вибери файли</strong>
        </label>
      </section>

      <section class="contract-review-files-panel">
        <div class="contract-review-panel-head">
          <p>${contractReviewFiles.length ? `${contractReviewFiles.length} файли` : "Файли ще не додано"}</p>
          ${contractReviewFiles.length ? `<button type="button" data-clear-contract-review-files>Очистити</button>` : ""}
        </div>
        ${contractReviewFiles.length ? `
          <ol class="contract-review-files">
            ${contractReviewFiles.map(renderContractReviewFile).join("")}
          </ol>
          <p class="${readinessClass}">${escapeHtml(readinessText)}</p>
        ` : `
          <p class="contract-review-empty">Додай пакет документів: основний договір, додатки, додаткові угоди, графік платежів або перелік майна.</p>
        `}
        <button class="primary-action primary-action-wide" type="button" data-run-contract-review ${canCompare ? "" : "disabled"}>${compareButtonText}</button>
        <p class="contract-review-note">Anodos не підставляє значення за припущенням: якщо дані не витягнуті з документа, клітинки залишаються порожніми.</p>
        ${contractReviewCopyMessage ? `<p class="contract-review-status">${escapeHtml(contractReviewCopyMessage)}</p>` : ""}
      </section>

      ${renderContractReviewTable()}
    </section>
  `;
}

function renderRegistration() {
  const localProfiles = authorizedUsers();
  screen.innerHTML = `
    <section class="registration-panel">
      <p class="eyebrow">Вхід</p>
      <h1>Профіль співробітника</h1>
      <p class="hero-copy">Вхід доступний лише з пошти, яка закінчується на @britmark.com. На телефоні зберігається локальна копія, а після підключення бази прогрес потрапляє в центральний реєстр.</p>

      <form id="registrationForm" class="registration-form">
        <label>
          <span>ПІБ</span>
          <input name="fullName" autocomplete="name" required placeholder="Наприклад, Олена Коваль" />
        </label>
        <label>
          <span>Email</span>
          <input name="email" type="email" autocomplete="email" autocapitalize="none" spellcheck="false" required placeholder="name@britmark.com" />
        </label>
        ${loginError ? `<p class="registration-error">${escapeHtml(loginError)}</p>` : ""}
        <button class="primary-action primary-action-wide" type="submit">Увійти</button>
      </form>
    </section>

    ${localProfiles.length ? `
      <section class="registration-panel">
        <p class="eyebrow">Цей телефон</p>
        <h2>Останні входи</h2>
        <div class="registered-user-list">
          ${localProfiles.map((user) => `
            <button class="registered-user-button" type="button" data-use-user="${escapeHtml(user.id)}">
              <span>${escapeHtml(user.fullName)}</span>
              <small>${escapeHtml(user.email || "локальний профіль")}</small>
            </button>
          `).join("")}
        </div>
      </section>
    ` : ""}
  `;
}

function renderHome() {
  if (activeSpace === "learning") {
    screen.innerHTML = `
      <section class="space-intro-card primary-tab-card" aria-labelledby="learningSpaceTitle">
        <div>
          <p class="eyebrow">Навчання</p>
          <h1 id="learningSpaceTitle">Навчальні модулі</h1>
          <p>Відео, короткі конспекти, практичні задачі та тести зібрані в одному просторі.</p>
        </div>
        <span class="space-intro-meta">${lessons.length} тем</span>
      </section>

      <section class="module-grid primary-tab-list" aria-label="Навчальні модулі">
        ${lessons.map(renderModuleCard).join("")}
      </section>
    `;
    return;
  }

  const hasScenarioQuery = scenarioSearchTerm.trim().length > 0;
  screen.innerHTML = `
    <section class="scenario-search-panel primary-tab-card primary-tab-action" aria-label="Сценарний пошук">
      <label class="scenario-search-label" for="scenarioSearch">
        <span>Сценарій пошуку</span>
        <input
          id="scenarioSearch"
          type="search"
          autocomplete="off"
          placeholder="Опишіть ситуацію Клієнта"
          value="${escapeHtml(scenarioSearchTerm)}"
        />
      </label>
      ${hasScenarioQuery ? "" : `<p class="scenario-hint">Опишіть ситуацію простими словами, а Anodos підкаже, де шукати відповідь.</p>`}
    </section>

    <section class="scenario-results-panel" aria-live="polite">
      <div id="scenarioSearchResults"></div>
    </section>

    <section class="module-grid primary-tab-list" aria-label="Страхові продукти">
      ${lessons.map(renderModuleCard).join("")}
    </section>
  `;
  renderScenarioSearchResults();
}

