function buildPresentationSlides(item) {
  const firstChecklist = item.checklist.slice(0, 3);
  const secondChecklist = item.checklist.slice(3, 6);
  return [
    {
      kicker: "вступ",
      title: item.video.title,
      body: item.outcome,
      points: item.video.chapters,
      script: "Починаємо з рамки: що саме треба зрозуміти, які документи читати першими і де найчастіше помиляється молодий фахівець."
    },
    {
      kicker: "логіка продукту",
      title: item.lessons[0]?.title || item.title,
      body: item.lessons[0]?.text || item.briefing[0],
      points: item.briefing,
      script: "На цьому кроці важливо не запам'ятовувати договір посторінково, а побачити внутрішню логіку продукту."
    },
    {
      kicker: "як читати договір",
      title: item.lessons[1]?.title || "Структура договору",
      body: item.lessons[1]?.text || "Рухаємося від об'єкта і покриття до лімітів, строків, території, винятків і процедури врегулювання.",
      points: firstChecklist,
      script: "Цей слайд перетворює договір на чек-лист. Так junior-фахівець не губиться у формулюваннях і бачить, що перевіряти."
    },
    {
      kicker: "ризики і винятки",
      title: item.lessons[2]?.title || "Критичні застереження",
      body: item.lessons[2]?.text || "Окремо перевіряються винятки, територіальні обмеження, спеціальні умови і питання до андеррайтера.",
      points: secondChecklist.length ? secondChecklist : item.checklist.slice(0, 3),
      script: "Тут фокус не на красивому переказі, а на професійній обережності: що можна сказати Клієнту, а що треба підтвердити."
    },
    {
      kicker: "закріплення",
      title: "Перед тестом",
      body: "Після презентації користувач має перейти до тесту і підтвердити, що розуміє практичну логіку продукту.",
      points: [`прохідний результат ${item.threshold}%`, "спиратися на джерела", "відповідати як фахівець, не як студент"],
      script: "Фінальний крок - коротка перевірка. Якщо матеріал зрозумілий, тест має бути не вгадуванням, а природним підтвердженням логіки."
    }
  ];
}

function renderPresentation(item) {
  if (item.video.src) {
    renderVideoPresentation(item);
    return;
  }

  const slides = buildPresentationSlides(item);
  const slide = slides[activeSlideIndex] || slides[0];
  const percent = Math.round(((activeSlideIndex + 1) / slides.length) * 100);
  screen.innerHTML = `
    ${renderModuleContextHead({
      item,
      eyebrow: "Відео-презентація",
      title: item.title,
      copy: item.focus,
      backAttributes: `data-open-module="${escapeHtml(item.id)}"`
    })}

    <section class="presentation-stage" aria-label="Навчальна відео-презентація">
      <div class="presentation-progress" aria-label="Слайд ${activeSlideIndex + 1} з ${slides.length}">
        <span style="width: ${percent}%"></span>
      </div>
      <div class="presentation-frame">
        <p class="section-kicker">${escapeHtml(slide.kicker)}</p>
        <h2>${escapeHtml(slide.title)}</h2>
        <p>${escapeHtml(slide.body)}</p>
        <div class="presentation-points">
          ${slide.points.map((point) => `<span>${escapeHtml(point)}</span>`).join("")}
        </div>
      </div>
      <div class="speaker-notes">
        <p class="section-kicker">Сценарій диктора</p>
        <p>${escapeHtml(slide.script)}</p>
      </div>
    </section>

    <section class="presentation-controls" aria-label="Керування презентацією">
      <button class="secondary-action" type="button" data-slide-prev ${activeSlideIndex === 0 ? "disabled" : ""}>Назад</button>
      <button class="primary-action" type="button" data-toggle-presentation>${presentationPlaying ? "Пауза" : "Відтворити"}</button>
      <button class="secondary-action" type="button" data-slide-next ${activeSlideIndex === slides.length - 1 ? "disabled" : ""}>Далі</button>
    </section>

    <section class="criteria-panel">
      <div>
        <p class="section-kicker">Після презентації</p>
        <h2>Перейти до тесту</h2>
        <p>Тест перевіряє не пам'ять на формулювання, а професійну логіку роботи з продуктом.</p>
      </div>
      <button class="primary-action" type="button" data-open-quiz="${item.id}">${escapeHtml(item.quizTitle || "Тест")}</button>
    </section>
  `;
}

