function lawEntries() {
  return insuranceLaw.entries || insuranceLaw.articles || [];
}

function normalizeLawText(value) {
  return String(value).toLocaleLowerCase("uk-UA");
}

function lawTerms() {
  return lawSearchTerm
    .trim()
    .split(/\s+/)
    .map(normalizeLawText)
    .filter(Boolean);
}

function entryLabel(entry) {
  if (entry.type === "article") {
    return `Стаття ${entry.number}. ${entry.title}`;
  }
  return entry.title;
}

function entryMatches(entry, terms) {
  if (!terms.length) {
    return true;
  }
  const haystack = lawSearchText(entry);
  return terms.every((term) => haystack.includes(term));
}

function lawSearchText(entry) {
  if (!entry.searchText) {
    entry.searchText = normalizeLawText([
      entry.number,
      entry.title,
      entry.section,
      ...(entry.paragraphs || [])
    ].join(" "));
  }
  return entry.searchText;
}

function filteredLawEntries() {
  const terms = lawTerms();
  return lawEntries().filter((entry) => entryMatches(entry, terms));
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function highlightLawText(value, terms) {
  const safe = escapeHtml(value);
  if (!terms.length) {
    return safe;
  }
  const pattern = terms.map(escapeRegExp).filter(Boolean).join("|");
  if (!pattern) {
    return safe;
  }
  return safe.replace(new RegExp(`(${pattern})`, "giu"), "<mark>$1</mark>");
}

function setActiveLawEntry(entryId) {
  activeLawEntryId = entryId;
  renderLawContent();
}

function currentLawEntry(entries) {
  if (!entries.length) {
    return null;
  }
  let current = entries.find((entry) => entry.id === activeLawEntryId);
  if (!current) {
    current = entries[0];
    activeLawEntryId = current.id;
  }
  return current;
}

function renderLaw() {
  const searchSummary = lawSearchTerm.trim() ? lawSearchTerm.trim() : "Відкрити пошук";
  screen.innerHTML = `
    <section class="reference-workspace reference-workspace-law primary-tab-workspace">
      <section class="reference-card reference-card-law primary-tab-card ${lawSearchCollapsed ? "law-search-collapsed" : ""}">
        <header class="reference-card-head reference-card-head-law">
          <div>
            <p class="eyebrow">ЗУпС</p>
            <h1>${escapeHtml(insuranceLaw.title)}</h1>
            <p>Пошук по тексту закону, преамбулі та прикінцевих положеннях.</p>
          </div>
          ${lawSearchCollapsed ? `
            <button class="law-search-mini-button" type="button" data-expand-law-search aria-expanded="false">
              <span>Пошук</span>
              <strong>${escapeHtml(searchSummary)}</strong>
            </button>
          ` : ""}
        </header>
        ${lawSearchCollapsed ? "" : `
          <section class="law-search-drawer" data-law-search-drawer aria-label="Пошук у законі">
            <button class="law-search-grip" type="button" data-law-search-grip data-collapse-law-search aria-label="Згорнути пошук">
              <span aria-hidden="true"></span>
            </button>
            <label class="law-search-label reference-search-label" for="lawSearch">
              <span>Пошук у законі</span>
              <input id="lawSearch" type="search" autocomplete="off" placeholder="Введіть запит для пошуку" value="${escapeHtml(lawSearchTerm)}" />
            </label>
            <div id="lawResults" class="reference-results"></div>
          </section>
        `}
        <section id="lawArticle" class="law-article-shell reference-article-shell" aria-live="polite"></section>
      </section>
    </section>
  `;
  renderLawContent();
}

function renderLawContent() {
  const resultsNode = document.getElementById("lawResults");
  const articleNode = document.getElementById("lawArticle");
  if (!articleNode) {
    return;
  }

  const terms = lawTerms();
  const entries = filteredLawEntries();
  const current = currentLawEntry(entries);
  const currentIndex = current ? entries.findIndex((entry) => entry.id === current.id) : -1;

  if (!current) {
    if (resultsNode) {
      resultsNode.innerHTML = `
        <div class="law-empty">
          <strong>Нічого не знайдено</strong>
          <p>Спробуй інше слово або прибери частину запиту.</p>
        </div>
      `;
    }
    articleNode.innerHTML = `
      <article class="law-article">
        <p class="section-kicker">Пошук</p>
        <h2>Нічого не знайдено</h2>
        <div class="law-body">
          <p>Відкрий пошук і спробуй інше слово або прибери частину запиту.</p>
        </div>
      </article>
    `;
    return;
  }

  if (resultsNode) {
    resultsNode.innerHTML = `
      <div class="law-toolbar">
        <p>${terms.length ? `${entries.length} збігів` : `${insuranceLaw.articleCount} статті`}</p>
        <select id="lawArticleSelect" aria-label="Перейти до статті">
          <option value="" disabled ${!terms.length && currentIndex === 0 ? "selected" : ""}>Оберіть необхідну статтю</option>
          ${entries.map((entry) => `<option value="${escapeHtml(entry.id)}" ${entry.id === current.id && (terms.length || currentIndex !== 0) ? "selected" : ""}>${escapeHtml(entryLabel(entry))}</option>`).join("")}
        </select>
      </div>
      ${terms.length ? `
        <div class="law-match-list" aria-label="Знайдені статті">
          ${entries.slice(0, 16).map((entry) => `
            <button class="${entry.id === current.id ? "law-match law-match-active" : "law-match"}" type="button" data-law-entry="${escapeHtml(entry.id)}">
              ${escapeHtml(entryLabel(entry))}
            </button>
          `).join("")}
        </div>
      ` : ""}
    `;
  }

  articleNode.innerHTML = `
    <article class="law-article">
      <p class="section-kicker">${escapeHtml(current.section || "Закон України")}</p>
      <h2>${escapeHtml(entryLabel(current))}</h2>
      <div class="law-body">
        ${(current.paragraphs || []).map((paragraph) => `<p>${highlightLawText(paragraph, terms)}</p>`).join("")}
      </div>
    </article>
  `;
  articleNode.scrollTop = 0;
}

